\source{standard-conjectures-abelian-fourfolds}
\label{conjkun} (Standard conjecture of K\"unneth type)
\source{standard-conjectures-abelian-fourfolds}


\noindent There exists a decomposition 
\[\mathfrak{h}(X)=\bigoplus_{n=0}^{2d} \mathfrak{h}^n(X)\] 
such that $R(\mathfrak{h}^n(X))=H^n(X)$ and $h^n(X)=h^{2d-n}(X)^{\vee}(-d).$

\source{standard-conjectures-abelian-fourfolds}
\label{kun+lef}
\source{standard-conjectures-abelian-fourfolds}
From now on we will assume that $X$ verifies the   Conjectures \ref{conjkun} and \ref{conjlef}.

\source{standard-conjectures-abelian-fourfolds}
\label{rempola}
\source{standard-conjectures-abelian-fourfolds}
If $k$ is embedded in ${\mathbb C}$, the Betti realization of $\langle \cdot, \cdot \rangle_{n,\mathrm{mot}}$ is a polarization of the Hodge structure $H^n(X)$.

\source{standard-conjectures-abelian-fourfolds}
\label{conjscht} (Standard conjecture of Hodge type)
\source{standard-conjectures-abelian-fourfolds}

\noindent For all $n \leq d/2$, the pairing  \[\langle \cdot, \cdot \rangle_{n} : \mathcal{Z}^{n,\mathrm{prim}}_{\mathrm{num}}(X)_{{\mathbb Q}}  \times  \mathcal{Z}^{n,\mathrm{prim}}_{\mathrm{num}}(X)_{{\mathbb Q}}  \longrightarrow {\mathbb Q}\]
of Definition \ref{defpairing} is positive definite.

\source{standard-conjectures-abelian-fourfolds}
\label{kerpairing}
\source{standard-conjectures-abelian-fourfolds}
The kernel of the pairing $\langle \cdot, \cdot \rangle_{n}$  on the vector space $\mathcal{Z}_{\hom}^{n}(X)_{{\mathbb Q}}$ is the space of algebraic classes  which are numerically trivial. The analogous statement holds true for $\mathcal{Z}_{\hom}^{n,\mathrm{prim}}(X)_{{\mathbb Q}}$.

\source{standard-conjectures-abelian-fourfolds}
\label{semipos} 
\source{standard-conjectures-abelian-fourfolds}
The pairing $\langle \cdot, \cdot \rangle_{n}$  is perfect on $\mathcal{Z}_{\mathrm{num}}^{n}(X)_{{\mathbb Q}}$. Moreover the pairing  is positive definite on  $\mathcal{Z}_{\mathrm{num}}^{n}(X)_{{\mathbb Q}}$ if and only if it is positive semidefinite on $\mathcal{Z}_{\hom}^{n}(X)_{{\mathbb Q}}$. The analogous statements hold true for $\mathcal{Z}_{\mathrm{num}}^{\mathrm{prim},n}(X)_{{\mathbb Q}}$.

\source{standard-conjectures-abelian-fourfolds}
\label{remHR}
\source{standard-conjectures-abelian-fourfolds}
If $k$ is embedded in ${\mathbb C}$ and if we work with Betti cohomology (cf. Remark \ref{rempola}), the Hodge--Riemann relations imply that $\langle \cdot, \cdot \rangle_{n}$  is positive definite on $(n,n)$-classes, hence on $\mathcal{Z}_{\hom}^{n}(X)_{{\mathbb Q}}$. In particular the standard conjecture of Hodge type holds true. 

Moreover, homological and numerical equivalence coincide (recall that we work under the Assumption  \ref{kun+lef}). The argument is due to Liebermann  \cite{Lieb} (see also \cite[Corollary 5.4.2.2]{Andmot}) and we recall it here.

If  $\alpha \in \mathcal{Z}_{\hom}^{n}(X)_{{\mathbb Q}}$ is a nonzero class  in codimension $n\leq d/2$ the inequality  $\langle \alpha, \alpha \rangle_{n}>0$ implies that $\alpha$ is not numerically trivial. On the other hand, the iterated intersection product with the hyperplane section $L$ induces an isomorphism $\mathcal{Z}_{\hom}^{n}(X)_{{\mathbb Q}}\cong \mathcal{Z}_{\hom}^{d-n}(X)_{{\mathbb Q}}$. Hence the intersection product $\mathcal{Z}_{\hom}^{n}(X)_{{\mathbb Q}}\times \mathcal{Z}_{\hom}^{d-n}(X)_{{\mathbb Q}}\rightarrow {\mathbb Q}$ is non-degenerate in one variable if and only if it is non-degenerate in the other, which implies that homological and numerical equivalence must coincide also in codimension $n\geq d/2$.

\source{standard-conjectures-abelian-fourfolds}

The pairing\label{segre} $\langle \cdot, \cdot \rangle_{1}$   on $\mathcal{Z}_{\mathrm{num}}^{1}(X)_{{\mathbb Q}}$ is positive definite. Equivalently, the pairing 
\source{standard-conjectures-abelian-fourfolds}
\[\mathcal{Z}^1_{\mathrm{num}}(X)_{{\mathbb Q}}\times \mathcal{Z}_{\mathrm{num}}^1(X)_{{\mathbb Q}} \longrightarrow {\mathbb Q} \hspace{1cm} D,D' \mapsto D\cdot D' \cdot L^{d-2}\]
is of signature  $ (s_+;s_-) = (1;  \rho_1-1)$ with
 $\rho_1=\dim \mathcal{Z}_{\mathrm{num}}^1(X)_{{\mathbb Q}}$.

\source{standard-conjectures-abelian-fourfolds}
\label{anypolarization}
\source{standard-conjectures-abelian-fourfolds}

The standard conjecture of Hodge type for a fourfold $X$  is equivalent to the statement that the intersection product
\[\mathcal{Z}^2_{\mathrm{num}}(X)_{{\mathbb Q}}\times \mathcal{Z}_{\mathrm{num}}^2(X)_{{\mathbb Q}} \longrightarrow {\mathbb Q}\]
is of signature  $ (s_+;s_-) = ( \rho_2 - \rho_1+1;  \rho_1-1)$ with
 $\rho_n=\dim \mathcal{Z}_{\mathrm{num}}^n(X)_{{\mathbb Q}}$.

In particular the conjecture does not depend on the ample divisor $L$ chosen.

\source{standard-conjectures-abelian-fourfolds}
 \label{reducefinite}
\source{standard-conjectures-abelian-fourfolds}
Let $X_0$ be a specialization of $X$. Suppose that $X_0$ as well satisfies the Assumption \ref{kun+lef} (with respect to the specialization of $L$). Then the standard conjecture of Hodge type for $X_0$ implies the standard conjecture of Hodge type for $X$.

\source{standard-conjectures-abelian-fourfolds}
\label{thmscht}
\source{standard-conjectures-abelian-fourfolds}
The standard conjecture of Hodge type holds for abelian fourfolds in positive characteristic.

\source{standard-conjectures-abelian-fourfolds}
\label{thmhomnum}
\source{standard-conjectures-abelian-fourfolds}
Let $A$ and $A_0$ be two   abelian fourfolds and suppose that  $A_0$ is a specialization of $A$. Let us fix a prime number $\ell$. If  $\ell$-adic homological equivalence on $A_0$ coincide with numerical equivalence on $A_0$ then the same holds true for $A$.

\source{standard-conjectures-abelian-fourfolds}
\label{thmclozel}
\source{standard-conjectures-abelian-fourfolds}
Let $A$ be an   abelian fourfold. Then numerical equivalence on $A$ coincides with $\ell$-adic homological equivalence on $A$ for infinitely many prime numbers $\ell$.

