\source{standard-conjectures-abelian-fourfolds}
\label{classic} Let $A$ be an abelian variety of dimension  $g$. Let ${\rm End}(A)$ be its ring of endomorphisms (as group scheme) and $\mathfrak{h}(A)\in \mathrm{CHM}(k)_{F}$ be its motive. Then the following holds:
\source{standard-conjectures-abelian-fourfolds}
\begin{enumerate}
\item\label{kunneth} \cite{DeMu} The motive $\mathfrak{h}(A)$ admits a Chow--K\"unneth decomposition 
\source{standard-conjectures-abelian-fourfolds}
\[\mathfrak{h}(A)=\bigoplus_{n=0}^{2g} \mathfrak{h}^n(A)\] natural in ${\rm End}(A)$ and such that 
\[R(\mathfrak{h}^n(A))= H^n(A).\] 
\item\label{kunn} \cite{Ku1} The intersection product induces a canonical isomorphism of graded algebras \[\mathfrak{h}^*(A)=\textnormal{Sym}^* \mathfrak{h}^1(A).\]
\source{standard-conjectures-abelian-fourfolds}
\item\label{kings}   \cite[Proposition 2.2.1]{Ki}  The action of ${\rm End}(A)$ on $\mathfrak{h}^1(A)$ (coming from naturality in (\ref{kunneth}))  induces an injective morphism of algebras  \[{\rm End}(A)\otimes_{{\mathbb Z}}F \hookrightarrow {\rm End}_{\mathrm{CHM}(k)_{F}}(\mathfrak{h}^1(A))\]
\source{standard-conjectures-abelian-fourfolds}
and if $A$ is isogenous to $B\times C$ then $\mathfrak{h}^1(A) =  \mathfrak{h}^1(B) \oplus \mathfrak{h}^1(C) .$
\item\label{polarization}   \cite{Ku2} The Chow--Lefschetz conjecture holds true for $A$. In particular, the classical isomorphism in $\ell$-adic cohomology  induced by a polarization $H_{\ell}^1(A)\cong H_{\ell}^1(A)^{\vee}(-1)$ lifts to an isomorphism
\source{standard-conjectures-abelian-fourfolds}
 \[\mathfrak{h}^1(A)\cong\mathfrak{h}^1(A)^{\vee}(-1).\] 
\end{enumerate}

\source{standard-conjectures-abelian-fourfolds}
\label{AHP}
\source{standard-conjectures-abelian-fourfolds}
We will need the above results also  in a slightly more general context, namely over the ring of integers of a $p$-adic field. Nowadays these results are known over very general bases, see \cite[Theorem 5.1.6]{OS2} or \cite[Theorem 3.3]{AHP}.

\source{standard-conjectures-abelian-fourfolds}
\label{remarkrank}
\source{standard-conjectures-abelian-fourfolds}
For motives of abelian type this definition is known to be independent of $R$, see for example  \cite[Corollary 3.5]{jannsen} and \cite[Corollary 1.6]{Ascona}.

\source{standard-conjectures-abelian-fourfolds}
\label{motivisupersingolari} 
\source{standard-conjectures-abelian-fourfolds}
Let $T$ be a motive of abelian type of dimension $d$. 
Consider   its space of algebraic classes modulo numerical equivalence \[V_Z = V_Z(T) =  {\rm Hom}_{\mathrm{NUM}(k)_{\mathbb Q}}(\mathds{1}, T).\] Then the  inequality 
$\dim_{\mathbb Q} V_Z \leq d$ holds.

Moreover, if the equality $\dim_{\mathbb Q} V_Z = d$ holds then we have the following facts:

\begin{enumerate}
\item All  realizations of $T$ are spanned by algebraic classes.
\item Numerical equivalence on ${\rm Hom}_{\mathrm{CHM}(k)_{\mathbb Q}}(\mathds{1},T)$ coincides with  homological equivalence (for all  cohomologies).
\item Call $L$ the field of coefficients of the realization $R$, then the equality $V_Z\otimes _{\mathbb Q} L = R(T)$ holds.
\end{enumerate}

