\source{standard-conjectures-abelian-fourfolds}
\label{remfrob}
\source{standard-conjectures-abelian-fourfolds}
Any maximal commutative ${\mathbb Q}$-subalgebra of ${\rm End}^0(A)$ must contain  $\tn{Frob}_A$ as the latter is contained in the center of ${\rm End}^0(A)$.

\source{standard-conjectures-abelian-fourfolds}
\label{decomposition}
\source{standard-conjectures-abelian-fourfolds}
Let $L$ and   $\Sigma$ be as in Notation  \ref{NotationCM}. Then, in $\mathrm{CHM} (k)_{L}$, the motive $\mathfrak{h}^1(A)$ decomposes into a sum of $2g$ motives  
\[\mathfrak{h}^1(A) =\bigoplus_{\sigma \in \Sigma} M_\sigma,\]
where the action of $b\in L_i$ on $M_\sigma$ induced by Theorem \ref{classic}(\ref{kings}) is given by multiplication by $\sigma(b)$ if $\sigma \in \Sigma_i$ and by multiplication by zero otherwise.  Moreover, each motive $ M_\sigma$ is of rank one (in the sense of Definition \ref{defrank}). Finally, if the CM-structure is $*$-stable, the isomorphism $p:  \mathfrak{h}^1(A)\cong\mathfrak{h}^1(A)^{\vee}(-1)$ of Theorem \ref{classic}(\ref{polarization}) restricts to an isomorphism \[M_\sigma\cong M_{\bar{\sigma}}^\vee(-1)\] for all $\sigma\in \Sigma$, and to the zero map 
\[ M_\sigma \stackrel{0}{\longrightarrow} M_{\sigma'}^\vee(-1) \]
for all $\sigma'\neq {\bar{\sigma}}$.

\source{standard-conjectures-abelian-fourfolds}
\label{primadecomposizione}
\source{standard-conjectures-abelian-fourfolds}
In the setting of Notation \ref{NotationCM} and Proposition \ref{decomposition}  the following holds:

\begin{enumerate}


\item\label{decomposizioneL} In $\mathrm{CHM} (k)_{L}$ the motive $\mathfrak{h}^n(A)$ decomposes into a sum 
\source{standard-conjectures-abelian-fourfolds}
\[\mathfrak{h}^n(A) =\bigoplus_{I\subset \Sigma, \vert I \vert = n} M_I,\]
with $M_I= \otimes_{\sigma \in I}M_\sigma$. Each motive $M_I$ is of rank one (in the sense of Definition \ref{defrank}).

Moreover, if the CM-structure is $*$-stable, then the motives $M_I$ and $M_J$ are mutually orthogonal  in $\mathrm{NUM}(k)_L$ with respect to $\langle \cdot, \cdot \rangle_{1,\mathrm{mot}}^{\otimes n}$ (Definition \ref{defpairingmot}) except if $I = \overline{J}$.

\item\label{decomposizioneQ} In $\mathrm{CHM} (k)_{{\mathbb Q}}$ the motive $\mathfrak{h}^n(A)$ decomposes into a sum of motives
\source{standard-conjectures-abelian-fourfolds}
\[\mathfrak{h}^n(A) =\bigoplus  \mathcal{M}_I,\]
where $\mathcal{M}_I$ is spanned by the factors of the form $M_{g(I)}$, with $g$ varying in ${\rm Gal}(L/{\mathbb Q}).$

Moreover, if the CM-structure is \nobreak{$*$-stable}, this decomposition in $\mathrm{NUM}(k)_{\mathbb Q}$  is orthogonal with respect to $\langle \cdot, \cdot \rangle_{1,\mathrm{mot}}^{\otimes n}$  (Definition \ref{defpairingmot}).

\end{enumerate}

\source{standard-conjectures-abelian-fourfolds}
\label{talvez}
\source{standard-conjectures-abelian-fourfolds}
Let  $\mathcal{M}_I \in \mathrm{CHM} (k)_{{\mathbb Q}}$ be a  direct factor of $\mathfrak{h}^{2n}(A)$ as constructed in Proposition \ref{primadecomposizione}(\ref{decomposizioneQ}). Then the following holds:
\begin{enumerate}
\item\label{generatoalgebrico} If the vector space ${\rm Hom}_{\mathrm{NUM}(k)_{\mathbb Q}}(\mathds{1}, \mathcal{M}_I (n))$ is not zero then 
\source{standard-conjectures-abelian-fourfolds}
\[\dim_{\mathbb Q} {\rm Hom}_{\mathrm{NUM}(k)_{\mathbb Q}}(\mathds{1}, \mathcal{M}_I (n)) = \dim \mathcal{M}_I.\]
In this case homological and numerical equivalence coincide on $ \mathcal{M}_I$ and the realizations of $ \mathcal{M}_I$ are spanned by algebraic classes.
\item\label{generatolefschetz}   If the vector space ${\rm Hom}_{\mathrm{NUM}(k)_{\mathbb Q}}(\mathds{1}, \mathcal{M}_I (n))$ contains a nonzero Lefschetz class (Definition \ref{defexotic}), then all algebraic  classes in 
\source{standard-conjectures-abelian-fourfolds}
it are Lefschetz.
\end{enumerate}

\source{standard-conjectures-abelian-fourfolds}
\label{HondaTate}
\source{standard-conjectures-abelian-fourfolds}
 For any CM-structure $B$ for $A$ (Definition \ref{definitionCM}), the pair  $(A,B)$ lifts to characteristic zero. More precisely there exists a $p$-adic field $K$ with ring of integers $W$ whose residue field $k'$ is a finite extension of $k$, and there is an abelian scheme $\mathcal{A}$ over $W$ together with an embedding $B\hookrightarrow {\rm End}^0(\mathcal{A})$, such that $\mathcal{A}\times_W k'$ is isogenous to $A \times_k k'$ (and the isogeny is $B$-equivariant).

\source{standard-conjectures-abelian-fourfolds}
\label{CMstab}
\source{standard-conjectures-abelian-fourfolds}
There exists a polarization on the abelian scheme $\mathcal{A}$ for which the CM-structure is $*$-stable

\source{standard-conjectures-abelian-fourfolds}
\label{lifting motives}
\source{standard-conjectures-abelian-fourfolds}
The decompositions of $\mathfrak{h}(A \times_k k')$ in Proposition \ref{primadecomposizione}  lift to decompositions of $\mathfrak{h}(\mathcal{A})\in  \mathrm{CHM} (W)$. Moreover, if the CM-structure of $A$ is $*$-stable (and if the polarisation lifts as well) then the orthogonality statement in Proposition \ref{primadecomposizione} holds true in $ \mathrm{CHM} (W)$ as well.

