\source{standard-conjectures-abelian-fourfolds}
\label{mainthm}
\source{standard-conjectures-abelian-fourfolds}
Let $K$ be a $p$-adic field, $W$  its ring of integers and $k$  its residue field. Let us fix an embedding $\sigma : K \hookrightarrow {\mathbb C}$.
Let \[M \in \mathrm{CHM}(W)_{\mathbb Q}\] be a motive in mixed characteristic and consider the motives induced by pullbacks $M_{\vert{\mathbb C}} \in \mathrm{CHM}({\mathbb C})_{\mathbb Q}$ and $M_{\vert{k}} \in \mathrm{CHM}(k)_{\mathbb Q}$. Consider $V_B$ and $V_Z$ the two ${\mathbb Q}$-vector spaces defined as
\[V_B = R_B(M_{\vert{\mathbb C}} ) \hspace{0.5cm}

\textrm{and} \hspace{0.5cm}
V_Z = {\rm Hom}_{\mathrm{NUM}(k)_{\mathbb Q}}(\mathds{1}, M_{\vert{k}}).\]


Let $q$ be a quadratic form on $M$, by which we mean a morphism in $ \mathrm{CHM}(W)_{\mathbb Q}$  of the form
$q: \textnormal{Sym}^2 M  \longrightarrow \mathds{1}.$
 Consider the two ${\mathbb Q}$-quadratic forms induced by $q$ on $V_B$ and $V_Z$ respectively, 
\[q_B=R_B(q)  \hspace{0.5cm} \textrm{and}  \hspace{0.5cm} q_Z(\cdot)= (q_{\vert{k}} \circ \textnormal{Sym}^2(\cdot)).\]
Suppose that the following holds:
\begin{enumerate}

\item\label{assumptiondim2} The two ${\mathbb Q}$-vector spaces $V_B$  and $V_Z$ are of dimension $2$.
\source{standard-conjectures-abelian-fourfolds}

\item The pairing $q_B$ on $V_B$ is a polarization of Hodge structures.

\end{enumerate}


Then the quadratic form $q_Z$ is positive definite.

\source{standard-conjectures-abelian-fourfolds}
\label{hypothesismainthm}
\source{standard-conjectures-abelian-fourfolds}
\begin{enumerate}
\item The main example of such a motive $M$ we have in mind is an exotic motive of an abelian fourfold (see Section \ref{sectionexotic}). Another example coming from geometry is given in Proposition \ref{propfermat}.
\item\label{homvsrat} One can actually make the  hypothesis a little bit more flexible and work with homological motives instead of Chow motives. This will not matter for our application to abelian varieties.
\source{standard-conjectures-abelian-fourfolds}
\end{enumerate}

\source{standard-conjectures-abelian-fourfolds}
\label{tortura}
\source{standard-conjectures-abelian-fourfolds}
Under the hypothesis of Theorem \ref{mainthm} the following holds:
\begin{enumerate}
\item The quadratic form $q_Z$   on $V_Z$ is non-degenerate. 
\item  Given a classical realization $R$, the vector space $R(M_{\vert{k}})$  is of dimension two.
\item Given a classical realization $R$, the vector space $R(M_{\vert{k}})$ is spanned by algebraic classes.
\item Numerical equivalence on ${\rm Hom}_{\mathrm{CHM}(k)_{\mathbb Q}}(\mathds{1},M_{\vert{k}})$ coincides with the homological equivalence for any classical cohomology.
\item\label{giorno} Fix a classical realization $R$ and call $L$ the field of coefficients of  $R$. Then the equality $V_Z\otimes _{\mathbb Q} L = R(M)$ holds.
\source{standard-conjectures-abelian-fourfolds}

\end{enumerate}

