\source{standard-conjectures-abelian-fourfolds}
\label{javier} \cite{Fonfon}
\source{standard-conjectures-abelian-fourfolds}
There are two integral ${\mathbb Q}_p$-algebras \[B_\textnormal{crys} \subset B_\mathrm{dR}\] the first endowed with  actions of the Galois group ${\rm Gal}_K$ and of the absolute Frobenius $\varphi$ and the second endowed with a discrete valuation,  
\[\nu: B_\mathrm{dR} \longrightarrow {\mathbb Z} \cup \{+\infty\}\]
hence in particular endowed with a decreasing filtration \[\tn{Fil}^i B_\mathrm{dR}=\{x \in B_\mathrm{dR}, \nu(x)\geq i\}\] verifying 
\[\tn{Fil}^i \cdot \tn{Fil}^j \subset \tn{Fil}^{i+j}.\] 
The ${\mathbb Q}_p$-algebra $ B_\mathrm{dR}$ contains $\overline{{\mathbb Q}}_p$, an algebraic closure of ${\mathbb Q}_p$, and the intersection $ B_\textnormal{crys} \cap \overline{{\mathbb Q}}_p$ is the biggest non-ramified extension of ${\mathbb Q}_p$ inside $\overline{{\mathbb Q}}_p$.

Finally, the following equality holds \cite[Theorem 5.3.7]{Fontp}
 \begin{equation}\label{eq:fontaine}(B_\textnormal{crys}^{\varphi={\rm id}} \cap \tn{Fil}^0B_\mathrm{dR})={\mathbb Q}_p.\end{equation}
\source{standard-conjectures-abelian-fourfolds}

\source{standard-conjectures-abelian-fourfolds}
\label{tsuji} 
\source{standard-conjectures-abelian-fourfolds}
There is an  equivalence of ${\mathbb Q}_p$-linear rigid categories 
\[D : \textnormal{REP} \longrightarrow \textnormal{MOD}\]
between the category $\textnormal{REP}$  of crystalline  ${\rm Gal}_K$-representations and the category $\textnormal{MOD}$ of admissible filtered $\varphi$-modules (see Convention (\ref{Hyodo-Kato})). This equivalence verifies the following properties:
\begin{enumerate}
\item\label{tsujican} There is a canonical identification 
\source{standard-conjectures-abelian-fourfolds}
\[ V \otimes B_\textnormal{crys}=  D(V)\otimes B_\textnormal{crys} \]
which is ${\rm Gal}_K$-equivariant and $\varphi$-equivariant. Moreover, the induced isomorphism
\[ V \otimes B_\mathrm{dR}=  D(V)\otimes B_\mathrm{dR} \]
respects the filtrations.

\item The functor $D$ is given by
\[V \mapsto D(V)= (V \otimes B_\textnormal{crys})^{{\rm Gal}_K}\]
and its inverse is given by
\[ [W\otimes B_\textnormal{crys}]^{\varphi={\rm id}} \cap  \tn{Fil}^0[W \otimes B_\mathrm{dR}] \mapsfrom W.\]

\item The equivalence $D$  is compatible with the two realization functors\footnote{This last fact is already present in the original works in $p$-adic Hodge theory although they are not written down in the motivic language. A reference is 
\cite[Theorem 1.2]{Niziol}, which can be immediately translated in our setting by  \cite[Proposition 4.2.5.1]{Andmot}.   This fact appears also in \cite[3.4.5]{Andmot} and it is implicitly  used in   \cite[7.4.1]{Andmot}. Nowadays much more general results are known, for instance this comparison of realization functors is available for mixed motives (i.e. motives of varieties which are not necessarely smooth and projective), see \cite[4.15]{NiziFred}.}
$R_p ((\cdot)_{\vert K}): \mathrm{CHM}(W) \rightarrow \textnormal{REP}$   and $R_\mathrm{HK} (\cdot): \mathrm{CHM}(W)\rightarrow \textnormal{MOD}$, namely we have
\[R_\mathrm{HK} (\cdot) = D \circ R_p ((\cdot)_{\vert K}).\]
\end{enumerate}

\source{standard-conjectures-abelian-fourfolds}
\label{cortsuji}
\source{standard-conjectures-abelian-fourfolds}
There are canonical identifications (commuting with the extra structures):
\begin{equation} \label{eq:tsuji}
\source{standard-conjectures-abelian-fourfolds}
 (V_{B,p},q_{B,p}) =[(V_{Z,p},q_{Z,p})\otimes B_\textnormal{crys}]^{\varphi={\rm id}} \cap  \tn{Fil}^0[(V_{Z,p},q_{Z,p})\otimes B_\mathrm{dR}].
\end{equation}
\begin{equation}\label{chissa}
\source{standard-conjectures-abelian-fourfolds}
 (V_{B,p},q_{B,p}) \otimes B_\textnormal{crys}=  (V_{Z,p},q_{Z,p}) \otimes B_\textnormal{crys}.
\end{equation}
\begin{equation}\label{chissa2}
\source{standard-conjectures-abelian-fourfolds}
 (V_{B,p},q_{B,p}) \otimes B_\mathrm{dR}=  (V_{Z,p},q_{Z,p}) \otimes B_\mathrm{dR}.
\end{equation}
Moreover, under these identifications,  the  equality of ${\mathbb Q}_p$-algebras  
\begin{equation}\label{stessaalgebra}
\source{standard-conjectures-abelian-fourfolds}
 {\rm End}_{{\rm Gal}_K}(V_{B,p}) = {\rm End}_{\varphi,\tn{Fil}^*}(V_{Z,p}\otimes {\rm Frac \,}(W(k)))
\end{equation}
holds.

\source{standard-conjectures-abelian-fourfolds}
\label{ordinarycase}
\source{standard-conjectures-abelian-fourfolds}
Suppose that the Hodge structure $V_B$ is of type $(0,0)$, then $q_{B,p}$ and $q_{Z,p}$ are isomorphic, hence Theorem \ref{mainthm}  holds true in this case.

\source{standard-conjectures-abelian-fourfolds}
\label{boris}\begin{enumerate}
\source{standard-conjectures-abelian-fourfolds}
\item This proposition (together with the arguments of the previous sections) gives a full proof of Theorem \ref{thmscht} for ordinary abelian fourfolds. Indeed, in the ordinary case, all Galois invariant classes lift to $(0,0)$-classes as it can be shown with Shimura--Taniyama  formula  \cite[Lemma 5]{TateBour}. See Appendix \ref{geometricexamples} for related discussions.
\item\label{duccio} The hypothesis that $V_B$ is of type $(0,0)$ corresponds to the only case where one can hope that the algebraic classes in $V_Z$ might be lifted to characteristic zero, in which case Theorem \ref{mainthm} would follow from the Hodge--Riemann relations. We find an amusing coincidence that this conjecturally easier  case corresponds to an easier $p$-adic analysis.
\source{standard-conjectures-abelian-fourfolds}
\item The proof of the above proposition shows that, under the comparison isomorphisms of Corollary \ref{cortsuji}, one has the equality of ${\mathbb Q}_p$-vector spaces $V_{B,p} = V_{Z,p}$. The Hodge conjecture  predicts   that actually also the two ${\mathbb Q}$-structures $V_B$ and $V_Z$ should coincide as well. Is it possible to show the equality $V_{B} = V_{Z}$ without assuming the Hodge conjecture? We do not know. 

An analogous question can be formulated in the $\ell$-adic setting. Consider an ordinary abelian variety $A$  (of any dimension) together with its canonical lifting $\tilde{A}$. Fix an algebraic class on $A$. Does it corresponds to a Hodge class on $\tilde{A}$? This is a priori weaker than the Hodge conjecture: we do not ask that the algebraic cycle does lift to an algebraic cycle. Notice that if the answer to the question was affirmative then one would have a proof of the standard conjecture of Hodge type for $A$.
\end{enumerate}

\source{standard-conjectures-abelian-fourfolds}
\label{ipos}
\source{standard-conjectures-abelian-fourfolds}
From now on we will suppose that the Hodge structure $V_B$ is not of type $(0,0)$. Equivalently there is a well-defined positive integer $i$ such that $\tn{Fil}^i(V_Z\otimes K)$ is a $K$-line and $\tn{Fil}^{i+1}(V_Z\otimes K)=0$.

\source{standard-conjectures-abelian-fourfolds}
\label{isotrop}
\source{standard-conjectures-abelian-fourfolds}
 Under Assumption \ref{ipos} the line 
 $\tn{Fil}^i(V_Z\otimes K)$ is isotropic.

\source{standard-conjectures-abelian-fourfolds}
\label{propendo}
\source{standard-conjectures-abelian-fourfolds}
Under  Assumption \ref{ipos} the
${\mathbb Q}_p$-algebra  ${\rm End}_{{\rm Gal}_K}(V_{B,p})$
is a field $F$ such that  $[F:{\mathbb Q}_p]=2$. Moreover, for all $v\in V_{B,p}$ and all $f\in F$,  we have the equality
\begin{equation} \label{eq:nonso}
\source{standard-conjectures-abelian-fourfolds}
 q_{B,p}(f \cdot v)=N_{F/{\mathbb Q}_p}(f) q_{B,p}(v).
\end{equation}

\source{standard-conjectures-abelian-fourfolds}
\label{nonso}
\source{standard-conjectures-abelian-fourfolds}
Keep Assumption  \ref{ipos} and let $F$ be the field of  Proposition \ref{propendo}. Then $F$ acts on $V_{Z,p}$ and the equality  (\ref{eq:tsuji}) is $F$-equivariant. Moreover,  for all $v\in V_{Z,p} $ and all $f\in F$  we have the equality
\begin{equation} \label{eq:nonso2}
\source{standard-conjectures-abelian-fourfolds}
q_{Z,p}(f \cdot v)=N_{F/{\mathbb Q}_p}(f) q_{Z,p}(v).
\end{equation}

\source{standard-conjectures-abelian-fourfolds}
\label{norms}
\source{standard-conjectures-abelian-fourfolds}
Keep Assumption  \ref{ipos} and let $F$ be the field of  Proposition \ref{propendo}. The following statements are equivalent:
\begin{enumerate}
\item The quadratic forms $q_{B,p}$ and $q_{Z,p}$ are isomorphic.
\item There exists a pair of nonzero vectors  $v_B\in V_{B,p}$ and $v_Z\in V_{Z,p}$ such that $q_{B,p}(v_B)$ and $q_{Z,p}(v_Z)$ are equal in ${\mathbb Q}_p^*/N_{F/{\mathbb Q}_p}(F^*).$
\item For any  pair of nonzero vectors  $v_B\in V_{B,p}$ and $v_Z\in V_{Z,p}$ we have that $q_{B,p}(v_B)$ and $q_{Z,p}(v_Z)$ are equal in ${\mathbb Q}_p^*/N_{F/{\mathbb Q}_p}(F^*).$
\end{enumerate}

\source{standard-conjectures-abelian-fourfolds}
\label{conventionF}
\source{standard-conjectures-abelian-fourfolds}
By the very construction of $F$, there are two actions of $F$ on  $V_{Z,p}\otimes F$ and this allows us to write the decomposition
\[V_{Z,p}\otimes F= V_{Z,+}  \oplus  V_{Z,-}\]
where $V_{Z,+}$ is the line where the two actions coincide and $V_{Z,-}$ is the line where the two actions are permuted by the non-trivial element of ${\rm Gal}(F/{\mathbb Q}_p)$. Using (\ref{eq:nonso2}), we see that $V_{Z,+}$ and $V_{Z,-}$ are also the two isotropic lines of the hyperbolic plane $V_{Z,p}\otimes F$. Notice that there is also an analogous decomposition
\[V_{B,p}\otimes F= V_{B,+} \oplus V_{B,-}\]
with analogous properties and that these decompositions are respected by Corollary \ref{cortsuji}. 

Finally, as $\tn{Fil}^i V_{Z,p}\otimes K$ is an isotropic line (Lemma \ref{isotrop}) it must coincide with $V_{Z,+}$ or  $V_{Z,-}$ (after extension of scalars to a field containing $F$ and $K$). We decide that the identification of $F$ and $K$ with a subfield of $\overline{\mathbb{Q}}_p$ is made to have the equality
\[\tn{Fil}^i V_{Z,p}\otimes  \overline{\mathbb{Q}}_p = V_{Z,+} \otimes  \overline{\mathbb{Q}}_p.\]

