\source{standard-conjectures-abelian-fourfolds}
\label{lubintate} (Lubin--Tate)
\source{standard-conjectures-abelian-fourfolds}
There is an element $t_2 \in B_\textnormal{crys}$ which verifies the following properties:
\begin{enumerate}
\item $t_2 \in \tn{Fil} ^{1} B_\mathrm{dR}-\tn{Fil} ^{2} B_\mathrm{dR}$.
\item  $ \varphi(t_2) \in \tn{Fil} ^{0} B_\mathrm{dR}-\tn{Fil} ^{1} B_\mathrm{dR}$.
\item $\varphi^2(t_2) = p \cdot t_2$.
\item Both $t_2 $ and  $ \varphi(t_2) $ are invertible in $B_{\textnormal{crys}}$.
\end{enumerate}

\source{standard-conjectures-abelian-fourfolds}
\label{brinon}
\source{standard-conjectures-abelian-fourfolds}
Fix a positive integer $i$ and define $\lambda_i \in B_\textnormal{crys}$ as
\[\lambda_i = (t_2/\varphi(t_2))^i .\]
Then $\lambda_i$ is a nonzero element of  $P_i$ and moreover it verifies
\[\lambda_i \cdot\varphi(\lambda_i) = 1/p^i.\]

\source{standard-conjectures-abelian-fourfolds}
\label{lubintateram} (Colmez)
\source{standard-conjectures-abelian-fourfolds}
For each uniformizer $\pi \in F$ there exists an element $t_\pi \in B_{\textnormal{crys},F}$  which verifies the following properties.
\begin{enumerate}
\item $t_\pi \in \tn{Fil} ^{1} B_\mathrm{dR}-\tn{Fil} ^{2} B_\mathrm{dR}$.
\item $\sigma (t_\pi) \in \tn{Fil} ^{0} B_\mathrm{dR}-\tn{Fil} ^{1} B_\mathrm{dR}$.
\item  $ \varphi(t_\pi) = \pi  \cdot t_\pi$.
\item Both $t_\pi $ and  $ \sigma(t_\pi) $ are invertible in $B_{\textnormal{crys},F}$.
\end{enumerate}

\source{standard-conjectures-abelian-fourfolds}
\label{remtame}
\source{standard-conjectures-abelian-fourfolds}
Let us recall the list of quadratic extensions of ${\mathbb Q}_p$. If $p\neq 2$, and if $a$ is an integer which is not a square modulo $p$, then ${\mathbb Q}_p(\sqrt{a})$ is the unramified quadratic extension, whereas ${\mathbb Q}_p(\sqrt{p})$ and ${\mathbb Q}_p(\sqrt{ap})$ are the two ramified quadratic extensions. 
If $p=2$,  ${\mathbb Q}_2(\sqrt{5})$ is the unramified quadratic extension, whereas ${\mathbb Q}_2(\sqrt{2}),{\mathbb Q}_2(\sqrt{6}),{\mathbb Q}_2(\sqrt{10}),{\mathbb Q}_2(\sqrt{14}),{\mathbb Q}_2(\sqrt{3})$ and $\mathbb{Q}_2(\sqrt{-1})$ are the six ramified quadratic extensions. 

In particular, it is almost always possible to find a uniformizer $\pi\in F$ such that 
$\sigma(\pi)=-\pi$ as in  Corollary \ref{brinonram}. The only exceptions are for  $p=2$ and  $F=\mathbb{Q}_2(\sqrt{3})$ or  $F=\mathbb{Q}_2(\sqrt{-1})$.  What follows treats these two exceptions.

\source{standard-conjectures-abelian-fourfolds}
\label{brinonwild}
\source{standard-conjectures-abelian-fourfolds}
We keep notation from Proposition  \ref{lubintateram} and we work  with $p=2$ and the field  $F=\mathbb{Q}_2(\sqrt{-1})$.  Let $\alpha \in {\mathbb Q}_{2^4}(\sqrt{-1})$ be an element  such that
\[\varphi(\alpha) =  \sqrt{-1} \cdot \alpha.\]
Define $\lambda_i \in B_{\textnormal{crys},F}$ as
\[\lambda_i = (\alpha \cdot t_{1-\sqrt{-1}} /\sigma(t_{1-\sqrt{-1}}))^i .\]
Then $\lambda_i$ is a nonzero element of  $P_{i}(F) $ and  moreover it verifies
\[\lambda_i \cdot\sigma(\lambda_i) = (\alpha  \cdot \sigma(\alpha) )^i.\]

\source{standard-conjectures-abelian-fourfolds}
