\item $\sigma (t_{2,\pi} ) , \varphi (t_{2,\pi} ) , \varphi \circ \sigma (t_{2,\pi} ) \in \tn{Fil} ^{0} B_\mathrm{dR}-\tn{Fil} ^{1} B_\mathrm{dR}$.
