\source{anticyclotomic-iwasawa-rational-elliptic-eisenstein}
\label{controlthm}
\source{anticyclotomic-iwasawa-rational-elliptic-eisenstein}
Assume that
\begin{itemize}

\item $E(\bQ_p)[p]=0$,
\item{} ${\rm rank}_{{\mathbb Z}}E(K)=1$,
\item{} $\#\sha(E/K)[p^\infty]<\infty$.
\end{itemize}
Then $\mathfrak{X}_E$ is a torsion $\Lambda$-module, and letting $\Fcal_E\in\Lambda$ be a generator of ${\rm char}_\Lambda(\mathfrak{X}_E)$, we have
\[
\# {\mathbb Z}_p /\Fcal_E(0) = 
\# \sha(E/K)[p^\infty]\cdot\biggl(  \dfrac{ \# ({\mathbb Z}_p / ( \frac{1-a_p+p}{p}) \cdot \mathrm{log}_{\omega_E} P) }{ [E(K): {\mathbb Z}\cdot P]_p }\biggr)^2\cdot\prod_{w\mid N} c_w^{}(E/K)_p,

\]	
where
\begin{itemize}
\item $P\in E(K)$ is any point of infinite order, 
\item $\log_{\omega_E}:E(K_v)_{/{\rm tors}}\rightarrow\bZ_p$ is the formal group logarithm associated to a N\'{e}ron differential $\omega_E$, 
\item $[E(K):{\mathbb Z}\cdot P]_p$ denotes the $p$-part of the index $[E(K):{\mathbb Z}\cdot P]$,
\item $c_w^{}(E/K)_p$ is the $p$-part of the Tamagawa number of $E/K_w$.
\end{itemize}

\source{anticyclotomic-iwasawa-rational-elliptic-eisenstein}

\label{thmGZ} 
\source{anticyclotomic-iwasawa-rational-elliptic-eisenstein}
Under the above hypotheses, $L(E/K,1)=0$ and 
\begin{displaymath}
L'(E/K,1)=u_K^{-2}c_E^{-2}\cdot\sqrt{\vert D_K\vert}^{-1}\cdot\Vert \omega_E \Vert^2\cdot \hat{h}(P_K),
\end{displaymath}
where $u_K=\#(\mathcal{O}_K^\times/{\pm{1}})$, 
$\hat{h}(P_K)$ is the canonical height of $P_K$, and $\Vert\omega_E\Vert^2=\iint_{E({\mathbb C})}|\omega_E \wedge \bar{\omega}_E|$.

\source{anticyclotomic-iwasawa-rational-elliptic-eisenstein}

\label{thmpadicGZ} 
\source{anticyclotomic-iwasawa-rational-elliptic-eisenstein}
Under the above hypotheses, let $p>2$ be a prime of good reduction for $E$ such that $p=v\bar{v}$ splits in $K$. Then
\[
\mathcal{L}_E(0)=c_E^{-2}\cdot\bigl(1-a_pp^{-1}+p^{-1}\bigr)^2\cdot{\rm log}_{\omega_E}(P_K)^2.
\]
where ${\rm log}_{\omega_E}:E(K_v)\rightarrow K_v$ is the formal group logarithm associated to $\omega_E$.

\source{anticyclotomic-iwasawa-rational-elliptic-eisenstein}

\label{thmGV}
\source{anticyclotomic-iwasawa-rational-elliptic-eisenstein}
Let $A/{\mathbb Q}$ be an elliptic curve, and let $p>2$ be a prime of good ordinary reduction for $A$. Assume that $A$ admits a cyclic $p$-isogeny with kernel $\Phi_A$, with the $G_\bQ$-action on $\Phi_A$ given by a character which is either ramified at $p$ and even, or unramified at $p$ and odd. If $L(A,1)\neq 0$ then
\begin{displaymath}
{\rm ord}_{p}\biggl(\frac{L(A, 1)}{\Omega_{A}}\biggr)={\rm ord}_{p}\biggl(\frac{\# \sha(A / {\mathbb Q})\cdot{\rm Tam}(A/{\mathbb Q})}{\#(A(\bQ)_{\rm tors})^2}\biggr),
\end{displaymath}
where ${\rm Tam}(A/\bQ)=\prod_{\ell} c_\ell(A/\bQ)$  
is the product over the bad primes $\ell$ of $A$ of the Tamagawa numbers of $A/\bQ_\ell$.

By \cite{kolyvagin-mw-sha}, if $L(A,1)\neq 0$ then ${\rm rank}_{\mathbb Z} A({\mathbb Q})=0$ and $\#\sha(A/{\mathbb Q})<\infty$; in particular, $\#{\rm Sel}_{p^\infty}(A/\bQ)=\#\sha(A/\bQ)[p^\infty]<\infty$. Letting $\Lambda_{\rm cyc}={\mathbb Z}_p\llbracket{\rm Gal}({\mathbb Q}_\infty/{\mathbb Q})\rrbracket$ be the cyclotomic Iwasawa algebra, by \cite[Thm.~4.1]{greenberg-cetraro} we therefore have
\begin{equation}\label{eq:greenberg-4.1}
\source{anticyclotomic-iwasawa-rational-elliptic-eisenstein}
\#{\mathbb Z}_p/\mathcal{F}_A(0)=\frac{\#\bigl({\mathbb Z}_p/(1-a_p(A)+p)^2\cdot\#\sha(A/{\mathbb Q})\cdot{\rm Tam}(A/\bQ)\bigr)}{\#\bigl({\mathbb Z}_p/(A({\mathbb Q})_{\rm tors})^2\bigr)},
\end{equation}
where $\mathcal{F}_A\in\Lambda_{\rm cyc}$ is a generator of the characteristic ideal of the dual Selmer group $Sel_{{\mathbb Q}_\infty}(T_pA,T_p^+A)^\vee$ in the notations of \cite[\S{3.6.1}]{skinner-urban}. Under the given assumptions, the cyclotomic main conjecture for $A$, i.e., the equality
\begin{equation}\label{eq:cyc-IMC}
\source{anticyclotomic-iwasawa-rational-elliptic-eisenstein}
(\mathcal{F}_A)=(\mathcal{L}_A)\subset\Lambda_{\rm cyc}
\end{equation}
where $\mathcal{L}_A$ is the $p$-adic $L$-function of Mazur--Swinnerton-Dyer, follows from the combination of \cite[Thm.~12.5]{kato-euler-systems} and\cite[Thm.~1.3]{greenvats}. By the interpolation property of $\mathcal{L}_A$, 
\begin{equation}\label{eq:interp-MSW}
\source{anticyclotomic-iwasawa-rational-elliptic-eisenstein}
\mathcal{L}_A(0)=\bigl(1-\alpha_p^{-1}\bigr)^2\cdot\frac{L(A,1)}{\Omega_A},
\end{equation}
where $\alpha_p\in{\mathbb Z}_p^\times$ is the unit root of $x^2-a_p(A)x+p$. Noting that ${\rm ord}_p(1-a_p(A)+p)={\rm ord}_p(1-\alpha_p^{-1})$, the result thus follows from the combination of (\ref{eq:greenberg-4.1}), (\ref{eq:cyc-IMC}), and (\ref{eq:interp-MSW}).

\begin{equation}\label{eq:greenberg-4.1}
\source{anticyclotomic-iwasawa-rational-elliptic-eisenstein}
\#{\mathbb Z}_p/\mathcal{F}_A(0)=\frac{\#\bigl({\mathbb Z}_p/(1-a_p(A)+p)^2\cdot\#\sha(A/{\mathbb Q})\cdot{\rm Tam}(A/\bQ)\bigr)}{\#\bigl({\mathbb Z}_p/(A({\mathbb Q})_{\rm tors})^2\bigr)},
\end{equation}

\source{anticyclotomic-iwasawa-rational-elliptic-eisenstein}
\label{thm:thmB}
\source{anticyclotomic-iwasawa-rational-elliptic-eisenstein}
Assume that $E[p]^{ss}=\mathbb{F}_p(\phi)\oplus\mathbb{F}_p(\psi)$ with $\phi\vert_{G_p}\neq\mathds{1},\omega$. Let $r\in\{0,1\}$. Then 
\[
{\rm corank}_{{\mathbb Z}_p}{\rm Sel}_{p^\infty}(E/{\mathbb Q}) = r 






\quad\Longrightarrow\quad
{\rm ord}_{s=1}L(E,s)=r,
\]
and so ${\rm rank}_{\mathbb Z} E({\mathbb Q})=r$ and $\#\sha(E/{\mathbb Q})<\infty$.

\source{anticyclotomic-iwasawa-rational-elliptic-eisenstein}
\label{cor:goldfeld}
\source{anticyclotomic-iwasawa-rational-elliptic-eisenstein}
Let $E$ be an elliptic curve over $\bQ$ with a rational $3$-isogeny. Then 
a positive proportion of quadratic twists of $E$ have algebraic and analytic rank equal to $1$
and a positive proportion of quadratic twists of $E$ have algebraic and analytic rank equal to $0$.

\source{anticyclotomic-iwasawa-rational-elliptic-eisenstein}
\label{rem:BKLS}
\source{anticyclotomic-iwasawa-rational-elliptic-eisenstein}
The qualitative result of Corollary~\ref{cor:goldfeld} was first obtained by Kriz--Li (see \cite[Thm.~1.5]{kriz-li}), but thanks to \cite{BKLS} (see esp. [\emph{op.\,cit.}, p.~2957]) our result {can lead} to better lower bounds on the proportion of rank~1 twists. In particular the proportions provided by \cite[Thm.~2.5]{BKLS} are the largest when the parity of the logarithmic Selmer ratios is equidistributed in quadratic families. The elliptic curve of smallest conductor over ${\mathbb Q}$ for which this happens is the elliptic curve having Cremona label $19a3$ given by the affine equation $y^2+y=x^3+x^2+x$. The explicit bounds of \cite{BKLS} and our result give that at least $41.6\%$ of its quadratic twists have analytic and algebraic rank equal to $1$ and at least $25\%$ have analytic and algebraic rank equal to $0$.

\source{anticyclotomic-iwasawa-rational-elliptic-eisenstein}
\label{thm:thmC}
\source{anticyclotomic-iwasawa-rational-elliptic-eisenstein}
Let $E/\bQ$ be an elliptic curve, and let $p>2$ be a prime of good ordinary reduction for $E$. Assume that $E$ admits a cyclic $p$-isogeny with kernel $C=\mathbb{F}_p(\phi)$, with $\phi:G_\bQ\rightarrow\mathbb{F}_p^\times$ such that
\begin{itemize}
\item $\phi\vert_{G_p}\neq\mathds{1},\omega$,
\item $\phi$ is either ramified at $p$ and odd, or unramified at $p$ and even.
\end{itemize}
If ${\rm ord}_{s=1}L(E,s)=1$, then 
\[
{\rm ord}_{p}\biggl(\frac{L'(E, 1)}{\operatorname{Reg}(E / {\mathbb Q}) \cdot \Omega_{E}}\biggr)={\rm ord}_{p}\biggl(\# \sha(E / {\mathbb Q}) \prod_{\ell \nmid \infty} c_{\ell}(E / {\mathbb Q})\biggr).
\]
In other words, the $p$-part of the Birch--Swinnerton-Dyer formula for $E$ holds.

Suppose ${\rm ord}_{s=1}L(E,s)=1$ and choose, as in the proof of Theorem~\ref{thm:thmB}, an imaginary quadratic field $K$ of discriminant $D_K$ such that
\begin{itemize}
\item[(a)] $D_K<-4$ is odd,
\item[(b)] every prime $\ell$ dividing $N$ splits in $K$,
\item[(c)] $p$ splits in $K$, say $p=v\bar{v}$,
\item[(d)] $L(E^K,1)\neq 0$.
\end{itemize}
Then ${\rm ord}_{s=1}L(E/K,s)=1$, which by Theorem~\ref{thmGZ} implies that the Heegner point $P_K\in E(K)$ has infinite order, and therefore ${\rm rank}_{\mathbb Z} E(K)=1$ and $\#\sha(E/K)<\infty$ by \cite{kolyvagin-mw-sha}. 
In particular, \eqref{eq:intro-sel} holds, and so all the hypotheses of Theorem \ref{thm:thmA} are satisfied. Thus there is a $p$-adic unit $u\in({\mathbb Z}_p^{{\rm ur}})^\times$ for which
\begin{equation}\label{eq:thmA}
\source{anticyclotomic-iwasawa-rational-elliptic-eisenstein}
\mathcal{F}_E(0)=u\cdot\mathcal{L}_E(0),
\end{equation}
where $\mathcal{F}_E\in\Lambda$ is a generator of ${\rm char}_\Lambda(\mathfrak{X}_E)$. The hypotheses on $\phi$ imply that $E(K)[p]=0$, and so Theorem~\ref{controlthm} applies with $P=P_K$, which combined with Theorem~\ref{thmpadicGZ} and the relations $(\ref{eq:comparison})$ and $(\ref{eq:thmA})$ 
yields the equality
\begin{equation}\label{eq:thmA-bis}
\source{anticyclotomic-iwasawa-rational-elliptic-eisenstein}
{\rm ord}_p\bigl(\#\sha(E/K)\bigr)=2\;{\rm ord}_p\bigl(c_E^{-1}u_K^{-1}\cdot[E(K):{\mathbb Z}.P_K]\bigr)-\sum_{w\in S}{\rm ord}_p\bigl(c_w(E/K)\bigr),
\end{equation}

On the other hand, the Gross--Zagier formula of Theorem~\ref{thmGZ} can be rewritten (see \cite[p.~312]{grosszagier}) as
\[
L'(E/K,1)=2^tc_E^{-2}u_K^{-2}\cdot\hat{h}(P_K)\cdot
\Omega_E\cdot\Omega_{E^K},
\]
where the power of $2$ is given by the number of connected components $[E(\mathbb{R}):E(\mathbb{R})^0]$.
This, together with the relations $L(E/K,s)=L(E,s)\cdot L(E^K,s)$ and
\[
\hat{h}(P_K)=[E(K):{\mathbb Z}\cdot P_K]^2\cdot{\rm Reg}_{}(E/K)=[E(K):{\mathbb Z}\cdot P_K]^2\cdot{\rm Reg}_{}(E/{\mathbb Q}),
\]
using that ${\rm rank}_{\mathbb Z} E^K({\mathbb Q})=0$ for the last equality, amounts to the formula
\begin{equation}\label{eq:GZ}
\source{anticyclotomic-iwasawa-rational-elliptic-eisenstein}
\frac{L'(E,1)}{{\rm Reg}(E/\bQ)\cdot\Omega_E}\cdot\frac{L(E^K,1)}{\Omega_{E^K}}=2^tc_E^{-2}u_K^{-2}\cdot[E(K):{\mathbb Z}\cdot P_K]^2.
\end{equation}
Note that $u_K=1$, since $D_K<-4$. Since $\sha(E/K)[p^\infty] \simeq\sha(E/\bQ)[p^\infty]\oplus\sha(E^K/\bQ)[p^\infty]$ as $p$ is odd, and   
\[
\sum_{w\vert\ell}{{\rm ord}}_p(c_w(E/K))={\rm ord}_p(c_\ell(E/\bQ))+{\rm ord}_p(c_\ell(E^K/{\mathbb Q}))
\]
for any prime $\ell$ (see \cite[Cor.~9.2]{skinner-zhang}), combining $(\ref{eq:thmA-bis})$ and (\ref{eq:GZ}) we arrive at
