\source{chabauty-coleman-bound-surfaces}
\label{ThmMainIntro} Let $p$ be a prime. Let $X$ be a smooth, geometrically irreducible, projective surface contained in an abelian variety $A$ of dimension $n\ge 3$, both defined over ${\mathbb Q}_p$ and having good reduction. Let $X'$ and $A'$ be the corresponding reductions modulo $p$. Let $G\le A({\mathbb Q}_p)$ be a finitely generated group with $\rk G\le 1$ and let $\Gamma$ be its $p$-adic closure in $A({\mathbb Q}_p)$.  Suppose that either of the following conditions holds:
\source{chabauty-coleman-bound-surfaces}
\begin{itemize}
\item[(i)] $n=3$, $X$ is of general type, $X'$ contains no elliptic curves over ${\mathbb F}_p^{alg}$, and $p>(128/9)c_1^2(X)^2$.  
\item[(ii)] $A'$ is simple over ${\mathbb F}_p^{alg}$, $p>3c_1^2(X)+2$, and there is an ample divisor $H$ on $A$ such that
$$
p> \frac{n!\cdot (3\deg(H^{2}.X) + \deg(H.K_X))^n}{n^n\cdot \deg(H^n)}.
$$
\end{itemize}
Then $X({\mathbb Q}_p)\cap \Gamma$ is finite and we have
\begin{equation}\label{EqnMainIntro}
\source{chabauty-coleman-bound-surfaces}
 \# X({\mathbb Q}_p)\cap \Gamma\le \# X'({\mathbb F}_p) + \frac{p-1}{p-2}\cdot \left(p+4p^{1/2} + 3\right)\cdot c_1^2(X).
 \end{equation}

\source{chabauty-coleman-bound-surfaces}
\label{RmkRHbd} By the Riemann Hypothesis for surfaces over finite fields \cite{Deligne} we have the estimate $|\# X'({\mathbb F}_p) - (p^2+1)|\le b_3p^{3/2} + b_2 p+b_1p^{1/2}$ where $b_j$ is the $j$-th Betti number of $X({\mathbb C})$. In particular, one can use $\# X'({\mathbb F}_p)\le p^2+b_3p^{3/2} + b_2 p+b_1p^{1/2}+1$  in \eqref{EqnMainIntro} to get a more uniform bound.
\source{chabauty-coleman-bound-surfaces}

\source{chabauty-coleman-bound-surfaces}
\label{RmkRH4p} When Theorem \ref{ThmMainIntro} applies, $p\ge 7$ and \eqref{EqnMainIntro} implies $ \# X({\mathbb Q}_p)\cap \Gamma< \# X'({\mathbb F}_p) + 4p\cdot c_1^2(X)$. Also, Remark \ref{RmkRHbd} shows  that $\# X'({\mathbb F}_p)$ is roughly of size $p^2$, say, for large $p$ and fixed Betti numbers of $X$. In this way, $\# X'({\mathbb F}_p)$ can be seen as the main term in the upper bound \eqref{EqnMainIntro}.
\source{chabauty-coleman-bound-surfaces}

\source{chabauty-coleman-bound-surfaces}
\label{ThmIntroA} Let $X$ be a smooth, geometrically irreducible, projective surface of general type contained in an abelian threefold $A$, both defined over ${\mathbb Q}$. Let $p> (128/9)\cdot  c_1^2(X)^2$ be a prime of good reduction for $X$ and $A$, and let $X'$ be the reduction of $X$ modulo $p$.  If $\rk A({\mathbb Q})\le 1$ and $X'$ contains no elliptic curves over ${\mathbb F}_p^{alg}$, then $X({\mathbb Q})$ is finite and
\source{chabauty-coleman-bound-surfaces}
$$
\#X({\mathbb Q}) \le \# X'({\mathbb F}_p) + \frac{p-1}{p-2}\cdot \left(p+4p^{1/2} + 3\right)\cdot c_1^2(X).
$$

\source{chabauty-coleman-bound-surfaces}
\label{RmkHyp1} A compact complex manifold $M$ is \emph{hyperbolic} if every holomorphic map $f:{\mathbb C}\to M$ is constant. If a complex projective surface is hyperbolic, then it is of general type (see Lemma \ref{LemmaGenTypeHyp}). So, in Theorem \ref{ThmIntroA} we may require that $X({\mathbb C})$ be hyperbolic instead of requiring general type ---depending on the application, this might be easier to check. In fact, there is no loss of generality in doing so: Under the assumptions of Theorem \ref{ThmIntroA}, the surface $X$ contains no elliptic curves over ${\mathbb Q}^{alg}$, hence, over  ${\mathbb C}$ (by specialization). Furthermore, $X$ is not an abelian surface because it is of general type. Since $X\subseteq A$, a result of Green \cite{Green} implies that $X({\mathbb C})$ is hyperbolic.
\source{chabauty-coleman-bound-surfaces}

\source{chabauty-coleman-bound-surfaces}
\label{RmkRk} It is expected that the rank of abelian varieties over ${\mathbb Q}$ of a fixed positive dimension is $0$ or $1$ a positive proportion of the time each ---ordering the abelian varieties, for instance, by (Faltings or Theta) height--- and this is proved for elliptic curves \cite{BhargavaShankar, BhargavaSkinner}. Thus, one can expect that the rank assumption in Theorems \ref{ThmIntroA} and \ref{ThmIntroB} is often satisfied in examples.
\source{chabauty-coleman-bound-surfaces}

\source{chabauty-coleman-bound-surfaces}
\label{CoroQuadratic} Let $C$ be a smooth, geometrically irreducible, projective curve over ${\mathbb Q}$ of genus $g\ge 3$ which is not hyperelliptic over ${\mathbb Q}^{alg}$ and such that its Jacobian $J$ has $\rk J({\mathbb Q})\le 1$.  Let  $p>(8g-10)^g$ be a prime of good reduction for $C$. Let $C'$ and $J'$ denote the reduction of $C$ and $J$ modulo $p$ respectively. Suppose that $C'$ is not hyperelliptic over ${\mathbb F}_p^{alg}$ and that $J'$ is geometrically simple. Then  $C^{(2)}({\mathbb Q})$ is finite and
\source{chabauty-coleman-bound-surfaces}
$$
\# C^{(2)}({\mathbb Q})\le \# (C')^{(2)}({\mathbb F}_p) +  \frac{p-1}{p-2}\cdot \left(p+4p^{1/2} + 3\right)\cdot (4g-9)(g-1).
$$

\source{chabauty-coleman-bound-surfaces}
\label{CoroQuadratic3} Let $C$ be a smooth, geometrically irreducible, projective curve over ${\mathbb Q}$ of genus $3$ which is not hyperelliptic over ${\mathbb Q}^{alg}$ and such that its Jacobian $J$ has $\rk J({\mathbb Q})\le 1$.  Let  $p\ge 521$ be a prime of good reduction for $C$ and denote by $C'$ the reduction of $C$ modulo $p$. Suppose that $C'$ is not hyperelliptic over ${\mathbb F}_p^{alg}$ and that $(C')^{(2)}$ does not contain elliptic curves over ${\mathbb F}_p^{alg}$. Then  $C^{(2)}({\mathbb Q})$  is finite and
\source{chabauty-coleman-bound-surfaces}
$$
\# C^{(2)}({\mathbb Q})\le \# (C')^{(2)}({\mathbb F}_p) +  6\cdot \frac{p-1}{p-2}\cdot \left(p+4p^{1/2} + 3\right) <  \# (C')^{(2)}({\mathbb F}_p) + 7.1\cdot p.
$$

