\source{chabauty-coleman-bound-surfaces}
\label{LemmaCompositionInt} Let $\phi: X\to Y$ and $\psi: Y \to Z$ be morphisms of $T$-schemes. Then $(\psi\circ \phi)^\bullet = \phi^\bullet \circ \psi^\bullet$.
\source{chabauty-coleman-bound-surfaces}

 First, we remark that this is not obvious. In particular, we claim that $(\psi\circ \phi)^\bullet$  and $\phi^\bullet \circ \psi^\bullet$ are equal, not just equal up to composition with an isomorphism. The result follows from Proposition 3.29 in \cite{GFthesis}; let us explain the details.

We consider the functors $\phi_*$, $\phi_*$, $\psi_*$, $\psi^*$, $(\psi\phi)_*$, and $(\psi\phi)^*$ mapping between the categories of $\Ocal_X$-modules, $\Ocal_Y$-modules, and $\Ocal_Z$-modules. We have $(\psi\phi)_*=\psi_*\phi_*$, while the functors $(\psi\phi)^*$ and $\phi^*\psi^*$ are isomorphic.

It is a routine exercise to check that for each $\Ocal_Z$-module $\Fcal$, the diagram 
$$
\begin{tikzcd}
\Fcal \arrow{d} \arrow{rr} & & \psi_*\psi^*\Fcal\arrow{d} \\
(\psi\phi)_*(\psi\phi)^*\Fcal \arrow{r}{\simeq} & (\psi\phi)_*\phi^*\psi^*\Fcal \arrow{r}{=} & \psi_*\phi_*\phi^*\psi^*\Fcal  
\end{tikzcd}
$$
commutes, where the left vertical arrow is the canonical map, and the right vertical arrow is obtained by applying $\psi_*$ to the canonical map of $\Ocal_Y$-modules $\psi^* \Fcal\to \phi_*\phi^*\psi^*\Fcal$. In particular, the following diagram commutes

\begin{equation}\label{EqnDiag1}
\source{chabauty-coleman-bound-surfaces}
\begin{tikzcd}
H^0(Z,\Omega^1_{Z/T}) \arrow{d} \arrow{rr} & & H^0(Z,\psi_*\psi^*\Omega^1_{Z/T})\arrow{d} \\
H^0(Z,(\psi\phi)_*(\psi\phi)^*\Omega^1_{Z/T}) \arrow{r}{\simeq} \arrow{d}{=}& H^0(Z,(\psi\phi)_*\phi^*\psi^*\Omega^1_{Z/T}) \arrow{r}{=} \arrow{d}{=}& H^0(Z,\psi_*\phi_*\phi^*\psi^*\Omega^1_{Z/T} ) \arrow{d}{=}\\
H^0(X,(\psi\phi)^*\Omega^1_{Z/T}) \arrow{r}{\simeq} & H^0(X,\phi^*\psi^*\Omega^1_{Z/T}) \arrow{r}{=} & H^0(Y,\phi_*\phi^*\psi^*\Omega^1_{Z/T}  ).
\end{tikzcd}
\end{equation}

Applying the functor $\phi_*\phi^*$ to the map $\psi^*\Omega^1_{Z/T}\to \Omega^1_{Y/T}$ we deduce that the diagram

\begin{equation}\label{EqnDiag2}
\source{chabauty-coleman-bound-surfaces}
\begin{tikzcd}
H^0(Z,\psi_*\psi^*\Omega^1_{Z/T})\arrow{r}{=}  \arrow{d} &H^0(Y,\psi^*\Omega^1_{Z/T})\arrow{r} \arrow{d} & H^0(Y,\Omega^1_{Y/T}) \arrow{d} \\
H^0(Z,\psi_*\phi_*\phi^*\psi^*\Omega^1_{Z/T})\arrow{r}{=} &H^0(Y,\phi_*\phi^*\psi^*\Omega^1_{Z/T})\arrow{r} & H^0(Y,\phi_*\phi^*\Omega^1_{Y/T}).
\end{tikzcd}
\end{equation}

commutes. By Proposition 3.29 in \cite{GFthesis}, the following diagram commutes

\begin{equation}\label{EqnDiag3}
\source{chabauty-coleman-bound-surfaces}
\begin{tikzcd}
H^0(X,(\psi\phi)^*\Omega^1_{Z/T})\arrow{r}{\simeq} \arrow{d} &H^0(X,\phi^*\psi^*\Omega^1_{Z/T})  \arrow{d}   &H^0(Y,\phi_*\phi^*\psi^*\Omega^1_{Z/T}) \arrow{l}{=} \arrow{d} \\
H^0(X,\Omega^1_{X/T}) &H^0(X,\phi^*\Omega^1_{Y/T}) \arrow{l} &H^0(Y,\phi_*\phi^*\Omega^1_{Z/T}) \arrow{l}{=}
\end{tikzcd}
\end{equation}

where the middle vertical arrow is obtained by applying $\phi^*$ to $\psi^*\Omega^1_{Z/T}\to \Omega^1_{Y/T}$. The result follows by combining \eqref{EqnDiag1}, \eqref{EqnDiag2}, and  \eqref{EqnDiag3}.

\source{chabauty-coleman-bound-surfaces}
\label{LemmaCommLoc} With the previous notation, the following diagram commutes
\source{chabauty-coleman-bound-surfaces}
$$
\begin{tikzcd}
H^0(Y,\Omega^1_{Y/T}) \arrow{d}   \arrow{r}{\phi^\bullet} & H^0(X,\Omega^1_{X/T})\arrow{d}\\
\Omega^1_{\Ocal_{Y,y}/\Ocal_{T,t}} \arrow{r}{\phi^\bullet_x} & \Omega^1_{\Ocal_{X,x}/\Ocal_{T,t}}
\end{tikzcd}
$$
where the vertical arrows are localization maps.

\source{chabauty-coleman-bound-surfaces}
 \label{ThmOver} Let $S$ be a smooth irreducible surface over $k$ and let $x\in S(k)$. Let $\omega_1,\omega_2\in H^0(S, \Omega^1_{S/k})$ be such that $\omega_1\wedge \omega_2\in H^0(S,\Omega^2_{S/k})$ is not the zero section. Let $D=\divi_S(\omega_1\wedge \omega_2)$ and let us write $D=a_1C_1+...+a_\ell C_\ell$ where $a_j$ are positive integers and $C_j$ are irreducible curves for each $j$ (possibly, $\ell=0$ if $D=0$). For each $j$, let $\nu_j:\widetilde{C}_j\to S$ be the normalization map of $C_j$ composed with the inclusion $C_j\to S$. 
\source{chabauty-coleman-bound-surfaces}

Let $m\ge 0$ be an integer such that there is a closed immersion $\phi: V_m^k\to S$ supported at $x$ (i.e. with $\phi(\zeta)=x$) which is $\omega_i$-integral for both $i=1$ and $i=2$. Then for every $\omega_0\in H^0(S,\Omega^1_{S/k})$ of the form $\omega_0=c_1\omega_1+c_2\omega_2$ with $c_1,c_2\in k$, we have
\begin{equation}\label{EqnOver}
\source{chabauty-coleman-bound-surfaces}
m\le \sum_{j=1}^\ell \sum_{y\in \nu_j^{-1}(x)} a_j\cdot \left({\rm ord}_y (\nu_j^\bullet (\omega_0))+1 \right).
\end{equation}

\source{chabauty-coleman-bound-surfaces}
\label{RmkOver1} If $x$ is not in the support of $D$, then the sum in \eqref{EqnOver} is empty and it gives the upper bound $m\le 0$, that is, $m=0$. This case is simpler and it is proved separately in Corollary \ref{Corom0}.
\source{chabauty-coleman-bound-surfaces}

\source{chabauty-coleman-bound-surfaces}
 \label{RmkSharp} The bound \eqref{EqnOver} is optimal in some non-trivial cases. For instance, assume that $k$ has characteristic different from $2$ and $3$.  We take $S={\mathbb A}^2_k={\rm Spec \,} k[s_1,s_2]$, $x=(0,0)$, $\omega_1=ds_1+s_1^2ds_2$, and $\omega_2=ds_1+s_2^2ds_2$. Thus, $\omega_1\wedge\omega_2 = (s_2-s_1)(s_2+s_1)ds_1\wedge ds_2$. Let $C_1$ and $C_2$ be defined by $s_1-s_2=0$ and $s_1+s_2=0$ respectively, so that $D=C_1+C_2$. Let $m=2$ and let $\phi :V_2^k\to {\mathbb A}^2_k$ be the map induced by the $k$-algebra morphism $k[s_1,s_2]\to E_2^k=k[z]/(z^3)$, $s_1\mapsto z\bmod z^3$, $s_2\mapsto 0$. The map $\phi$ is a closed immersion supported at $x$ which is $\omega_i$-integral for $i=1,2$, as $\Omega^1_{E_2^k/k}=(k[z]/(z,3z^2))dz=(k[z]/(z^2))dz$. For $\omega_0=\omega_1,\omega_2$,  \eqref{EqnOver} becomes $m\le 1\cdot (0+1) + 1\cdot (0+1)=2$.
\source{chabauty-coleman-bound-surfaces}

\source{chabauty-coleman-bound-surfaces}
 \label{LemmaGenOver} There are local parameters $s_1,s_2\in \mfrak_{S,x}$ at $x$ such that $\phi^\#_\zeta(s_1)=z \bmod z^{m+1}$ and $\phi^\#_\zeta(s_2)=0$. Furthermore, $\ker(\phi^\#_\zeta)=(s_1^{m+1},s_2)$.
\source{chabauty-coleman-bound-surfaces}

\source{chabauty-coleman-bound-surfaces}
 \label{LemmaLocDiff} Let $\omega\in H^0(S, \Omega^1_{S/k})$ be such that the map $\phi:V_m^k\to S$ is $\omega$-integral. Then there are $G_1,G_2,G_3\in \Ocal_{S,x}$ such that the germ of $\omega$ at $x$ is 
\source{chabauty-coleman-bound-surfaces}
$$
\omega_x=(G_1s_1^m + G_2s_2)ds_1 + G_3ds_2 \in \Omega^1_{\Ocal_{S,x}/k}.
$$

\source{chabauty-coleman-bound-surfaces}
 \label{Corom0} If $x$ is not in the support of $D$, then $m=0$.
\source{chabauty-coleman-bound-surfaces}

\source{chabauty-coleman-bound-surfaces}
 \label{LemmaIndividual} Let $\omega\in H^0(S,\Omega^1_{S/k})$ be such that $\phi:V_m^k\to S$ is $\omega$-integral. Take $j$ with $1\le j\le \ell$ and fix a choice of $y\in \nu_j^{-1}(x)$, if any. Then we have
\source{chabauty-coleman-bound-surfaces}
$$
{\rm ord}_y (\nu_j^\bullet(\omega))\ge \min\{m, {\rm ord}_{s_1}(\pi(F_{j,y})) -1\}.
$$

 Let $t\in \mfrak_{\widetilde{C}_j, y}$ be a local parameter. Thus, $\widehat{\Ocal}_{\widetilde{C}_j,y}=k[[t]]$. The morphism $\nu_{j}:\widetilde{C}_j\to S$ induces the map $\nu_{j,y}^\#: \Ocal_{S,x}\to \Ocal_{\widetilde{C}_j,y}$ and the map on completions $\widehat{\nu}_{j,y}^\#:k[[s_1,s_2]]\to k[[t]]$. 

For $i=1,2$ let $h_i=\nu_{j,y}^\#(s_i)\in \mfrak_{\widetilde{C}_j,y}\subseteq t\cdot k[[t]]$. Lemma \ref{LemmaLocDiff} gives $\omega_x=(G_1s_1^m + G_2s_2)ds_1 + G_3ds_2$ for some $G_1,G_2,G_3\in \Ocal_{S,x}$. By Lemma \ref{LemmaCommLoc} we get
$$
(\nu_j^\bullet(\omega))_y = \nu_{j,y}^\bullet(\omega_x) = \left(\nu_{j,y}^\#(G_1)h_1^m +\nu_{j,y}^\#(G_2)h_2\right)h_1'dt + \nu_{j,y}^\#(G_3)h_2'dt
$$
where $h_i'\in \Ocal_{\widetilde{C}_j,y}$ are defined by the relation $dh_i=h_i'dt$ in $\Omega^1_{\Ocal_{\widetilde{C}_j,y}/k}$ (as $dt$ generates). It follows that

\begin{equation}\label{EqnKeyVal1}
\source{chabauty-coleman-bound-surfaces}
{\rm ord}_y(\nu^\bullet(\omega)) = {\rm ord}_t\left((\nu_{j,y}^\#(G_1)h_1^m +\nu_{j,y}^\#(G_2)h_2)h_1' + \nu_{j,y}^\#(G_3)h_2'\right).
\end{equation}

Note that $F_{j,y}(h_1,h_2)=\widehat{\nu}_{j,y}^\#(F_{j,y})=0$ in $k[[t]]$, since $(F_{j,y})\subseteq k[[s_1,s_2]]$ is the branch of $C_j$ corresponding to $y$. As $F_{j,y}\in k[[s_1,s_2]]$ is irreducible, Lemma \ref{LemmaPloski} gives 

\begin{equation}\label{EqnKeyVal2}
\source{chabauty-coleman-bound-surfaces}
{\rm ord}_t (h_2) \ge {\rm ord}_{s_1} (\pi(F_{j,y})).
\end{equation}

The relation $dh_i=h_i'dt$ in $\Omega^1_{\Ocal_{\widetilde{C}_j,y}/k}$  shows that in $\widehat{\Ocal}_{\widetilde{C}_j,y}=k[[t]]$, the power series $h_i'$ is the formal derivative of $h_i$. Hence, for $i=1,2$ we have

\begin{equation}\label{EqnKeyVal3}
\source{chabauty-coleman-bound-surfaces}
{\rm ord}_t (h_i') \ge {\rm ord}_t (h_i)-1.
\end{equation}

Using \eqref{EqnKeyVal1}, \eqref{EqnKeyVal2}, and \eqref{EqnKeyVal3} we finally deduce
$$
\begin{aligned}
{\rm ord}_y(\nu_j^\bullet(\omega))&\ge \min\left\{ {\rm ord}_t\left(\nu_{j,y}^\#(G_1)h_1^mh_1' \right), {\rm ord}_t\left(  \nu_{j,y}^\#(G_2)h_2h_1' + \nu_{j,y}^\#(G_3)h_2'  \right)   \right\} \\
& \ge \min\left\{ (m+1) {\rm ord}_t(h_1) -1, {\rm ord}_t(h_2)-1   \right\} \\
& \ge \min\left\{  m , {\rm ord}_{s_1}(\pi(F_{j,y}))-1  \right\}.
\end{aligned}
$$

