\source{higher-siegel-weil-unitary-nonsingular-terms}
\label{lem:Whi}
\source{higher-siegel-weil-unitary-nonsingular-terms}
Let $L$ be a Hermitian $\cO_{F'}$-lattice of rank $n$. Let $T=((x_i, x_j))_{1\le i,j\le n}$ be the fundamental matrix of an $\cO_{F'}$-basis $\{x_1,\ldots, x_n\}$ of $L$, an $n\times n$ Hermitian matrix over $F$. Let $\th$ be a generator of $\omega_{\cO_{F}}$ so that $T\th\in \Herm_{n}(F,\omega_{F})$. Then
  \begin{align*}
W_{T\th}(1, s, \Phi)={\mathcal L}_{n,F'/F}(s)^{-1} \Den(q^{-2s},  L).
  \end{align*}
  Here $\Phi$ is the local unramified section normalized by $\Phi(1_{2n},s)=1$.

Note that by Theorem \ref{th:CY} 
$${\mathcal L}_{n,F'/F}( j)=\Den(\iden^{n+2j},  \iden^{n})^{-1}. $$
It is known that $W_{T\th}(1, s, \Phi)$ is a rational function in $q^{s}$.
Therefore the formula is equivalent to
  \begin{align*}
W_{T\th}(1, j, \Phi)= \Den(\iden^{n+2j},  L).
  \end{align*}
  for all integer $j\geq 0$. 
In the non-split case this is essentially \cite[Prop.~10.1]{KRII} (cf. \cite[\S3.3]{LZ1}), which can be easily modified to the split case. We note that $W_{T\th}$ is the same as $W_{T}$ in {\em loc. cit.}.

We define   
 the density polynomial for $(\cE_v,a)$ as 
 \begin{equation}
 \label{def Den Ev}
\source{higher-siegel-weil-unitary-nonsingular-terms}
 \Den_{v}(T, (\cE_v,a)):=\Den(T, \cE_v).

\source{higher-siegel-weil-unitary-nonsingular-terms}
\label{th:Eis Den} 
\source{higher-siegel-weil-unitary-nonsingular-terms}
Let $\cE$ be a vector bundle over $X'$ of rank $n$.  

Then 
\begin{equation}\label{eq:reg}
\source{higher-siegel-weil-unitary-nonsingular-terms}
E^{\rm reg}(m(\cE),s,\Phi)=\sum_{a: \cE\hookrightarrow \s^{*}\cE^\vee}E_{a}(m(\cE), s,\Phi)
\end{equation}
where the sum runs over all injective Hermitian maps  $a: \cE\to \s^{*}\cE^\vee $. Moreover, we have
\begin{equation}\label{Ea Den}
\source{higher-siegel-weil-unitary-nonsingular-terms}
E_{a}(m(\cE),s,\Phi)=\chi(\det(\cE))q^{-\deg(\cE)( s-n/2)-\frac{1}{2}n^2\deg\omega_X }{\mathcal L}_n(s) ^{-1} \Den(q^{-2s}, (\cE,a)).
\end{equation}


From the definitions it is clear that
\begin{equation*}
E^{\rm reg}(m(\cE),s,\Phi)=\sum_{a:\cE\dashrightarrow\s^{*}\cE^{\vee}}E_{a}(m(\cE),s,\Phi)
\end{equation*}
where $a$ runs over {\em rational} Hermitian maps $\cE\dashrightarrow \s^* \cE^{\vee}$ that are generically nonsingular.


Now let $a:\cE\dashrightarrow\s^{*}\cE^{\vee}$ be such a rational nonsingular Hermitian map. We continue with the convention defining  \eqref{eq:def Ea cE} 

\begin{equation}\label{EaET}
\source{higher-siegel-weil-unitary-nonsingular-terms}
E_{a}(m(\cE),s,\Phi)=E_{T}(m(\a), s,\Phi).
\end{equation}
By \eqref{Eis factor Wh} and \eqref{eq:ch base}, and noting that the character $\chi$ is trivial on the norm of $\BA_{F'}^\times$, we have 
\begin{equation}\label{ETWh}
\source{higher-siegel-weil-unitary-nonsingular-terms}
E_{T}(m(\alpha),s,\Phi)=\chi(\det(\alpha))|\alpha|_{F'}^{-s+n/2} |\omega_{X}|^{-\frac{1}{2}n^2} \prod_{v\in |X|}W_{T_{v}}(1,s,\Phi_{v}).
\end{equation}
If the ($\omega_{F_v}$-valued) Hermitian form $T_{v}$ does not have integral entries, then $W_{T_{v}}(1,s,\Phi_{v})=0$ (since $\Phi$ is invariant under $N_{n}(\cO_{v})$). Therefore $E_{T}(m(\alpha),s,\Phi)$ is nonzero only when  $T_{v}$ is integral for all $v$, i.e., $a$ is an everywhere regular Hermitian map $\cE\hookrightarrow\s^{*}\cE^{\vee}$. This proves \eqref{eq:reg}.

For such $a: \cE\hookrightarrow\s^{*}\cE^{\vee}$, by Lemma \ref{lem:Whi}, the right side of \eqref{ETWh} is
\begin{equation}\label{WhDen}
\source{higher-siegel-weil-unitary-nonsingular-terms}
\chi(\det(\alpha))|\det (\alpha)|_{F'}^{-s+n/2} |\omega_{X}|^{-\frac{1}{2}n^2} \prod_{v\in |X|}\frac{1}{{\mathcal L}_{n, F_v'/F_v}(s) }  \Den(q_v^{-2s},  \cE_{v}),
\end{equation}
where, by choosing a generator of $\omega_{\cO_{F_v}}$, the $\cO_{F_v'}$-module $\cE_v$ is endowed with the Hermitian form (valued in $\cO_{F_v}$) induced by the $\omega_{X}$-valued Hermitian form $a$.

By $\chi(\det(\alpha))=\chi(\det(\cE))$, $|\det (\alpha)|_{F'}=q^{\deg(\cE)}$, and \eqref{def Den Ev}, we obtain
\begin{equation*}
\Den(q^{-2s}, (\cE,a))=\prod_{v\in |X|}\Den(q^{-2s}_{v}, (\cE_{v},a_{v}))=\prod_{v\in |X|}\Den(q_v^{-2s},  \cE_{v}).
\end{equation*}
Combining these facts with \eqref{EaET}, \eqref{ETWh} and \eqref{WhDen}, we get \eqref{Ea Den}.

