The action of $w\in S_{d}$ on $\cohog{*}{\cB_{\cQ}}$ sends $\cohog{*}{\cB_{\cQ}(y)}$ to $\cohog{*}{\cB_{\cQ}(y\c w^{-1})}$, for all $y\in \Sigma(Z)$.

It suffices to check the statement for each simple reflection $s_{i}$ switching $i$ and $i+1$ ($1\le i\le d-1$). Let $\wt\Coh^{i}_{d}(X)$ be the moduli stack classifying chains of torsion coherent sheaves $0\subset\cQ_{1}\subset\cdots\subset\cQ_{i-1}\subset\cQ_{i+1}\subset\cdots \subset\cQ_{d}$ with $\cQ_{i}$ missing. Then we have a factorization
\begin{equation*}
\pi^{\Coh}_{d}: \wt\Coh_{d}(X)\xr{\r_{i}}\wt\Coh^{i}_{d}(X)\xr{\pi_{i}}\Coh_{d}(X).
\end{equation*}
The map $\r_{i}$ is an \'etale double cover over the open dense locus  $\wt\Coh^{i,\hs}_{d}(X)$  where $\cQ_{i+1}/\cQ_{i-1}$ (which has length $2$) is supported at two distinct points. The map $\r_{i}$ is small by Lemma \ref{lem: Laumon small}, and $R\r_{i*}\Qlbar$ carries an involution $\wt s_{i}$, which induces an involution $\wt s_{i}$ on $R\pi_{i*}R\r_{i*}\Qlbar\cong \Spr_{d}$. This action coincides with the action of $s_{i}$ over $\Coh_{d}(X)^{\c}$, hence coincides with $s_{i}$ everywhere. 

Let $\cB_{\cQ}^{i}=\pi_{i}^{-1}(\cQ)$. By considering the support of the successive quotients, we have a decomposition of $\cB_{\cQ}^{i}$ by the orbit set $\Sigma(Z)/\j{s_{i}}$. When $y\in\Sigma(Z)$ satisfies $y\ne y\c s_{i}$, the $s_{i}$-orbit $\y=\{y,y\c s_{i}\}$ gives an open and closed substack $\cB^{i}_{\cQ}(\y)\subset \cB_{\cQ}^{i}$, such that $\r^{-1}_{i}(\cB^{i}_{\cQ}(\y))=\cB_{\cQ}(y)\coprod\cB_{\cQ}(y\c s_{i})$, and $\cB^{i}_{\cQ}(\y)\subset \wt\Coh^{i,\hs}_{2d}$. Therefore in this case the action of $\wt s_{i}$ on $\cohog{*}{\r^{-1}_{i}(\cB^{i}_{\cQ}(\y))}$ comes from the involution on $\cB_{\cQ}(y)\coprod\cB_{\cQ}(y\c s_{i})$ that interchanges the two components. Since $\wt s_{i}=s_{i}$, this proves the statement for $s_{i}$ and $y$ such that $y\ne y\c s_{i}$. For $y=y\c s_{i}$ the statement is vacuous. This finishes the proof.

\source{higher-siegel-weil-unitary-nonsingular-terms}
\label{l:min w} Let $y,y'\in \Sigma(Z)$ and let $w\in S_{d}$ be such that $y\c w^{-1}=y'$. Assume that $w$ has minimal length (in terms of the simple reflections $s_{1},\cdots, s_{d-1}$) among such elements (such $w$ is unique). Then the Springer action $w: \cohog{*}{\cB_{\cQ}(y)}\to \cohog{*}{\cB_{\cQ}(y')}$ is induced by the composition of the canonical isomorphisms $\b_{y,y'}:=\b_{y'}^{-1}\c\b_{y}: \cB_{\cQ}(y)\stackrel{\sim}{\longrightarrow} \cB_{\cQ}(y')$. In particular, $w$ sends the fundamental class of $\cB_{\cQ}(y)$ to the fundamental class of $\cB_{\cQ}(y')$.
\source{higher-siegel-weil-unitary-nonsingular-terms}

\source{higher-siegel-weil-unitary-nonsingular-terms}
\label{c:Sind} Let $y\in \Sigma(Z)$ and $S_{y}\cong \prod_{x\in Z}S_{d_{x}}$ be the stabilizer of $y$ under $S_{d}$.  There is an isomorphism of graded $S_{d}$-representations
\source{higher-siegel-weil-unitary-nonsingular-terms}
\begin{equation*}
\cohog{*}{\cB_{\cQ}}\cong \Ind^{S_{d}}_{S_{y}}\cohog{*}{\cB_{\cQ}(y)}\cong \Ind^{S_{d}}_{S_{y}}\left(\bigotimes_{x\in Z}\cohog{*}{\cB_{\cQ_{x}}}\right).
\end{equation*}
Here on the right side, each factor $S_{d_{x}}$ of $S_{y}$ acts on the tensor factor indexed by $x$ (for $x\in Z$) via the Springer action in Corollary \ref{c:Coh Spr} on $(\Spr_{d_{x}})_{\cQ_{x}}$.

 By Lemma \ref{l:perm Coh},  $\cohog{*}{\cB_{\cQ}(y\c w^{-1})}=w\cohog{*}{\cB_{\cQ}(y)}$ for $w\in S_{d}$. In particular, $\cohog{*}{\cB_{\cQ}(y)}$ is stable under $S_{y}$, and  $\cohog{*}{\cB_{\cQ}}\cong \Ind^{S_{d}}_{S_{y}}\cohog{*}{\cB_{\cQ}(y)}$. By \eqref{BQy} and the K\"unneth formula, we have $\cohog{*}{\cB_{\cQ}(y)}\cong \ot_{x\in Z}\cohog{*}{\cB_{\cQ_{x}}}$. 

It remains to check that the action of $S_{y}$ on $\cohog{*}{\cB_{\cQ}(y)}$ (as the restriction of the $S_{d}$-action on $\cohog{*}{\cB_{\cQ}}$) is the same as the tensor product of the Springer action of $S_{d_{x}}$ on  $\cohog{*}{\cB_{\cQ_{x}}}$. Since the action of $S_{d}$ on $\Sigma(Z)$ is transitive, it suffices to check this statement for a particular $y\in \Sigma(Z)$. 

Order points in $Z$ as $x_{1},\cdots, x_{r}$.  Let $y_{0}\in \Sigma(Z)$ be the unique increasing function, i.e. such that if $i< j$ then the index of $y_0(i)$ is less than or equal to the index of $y_0(j)$. Let $d_{i}=d_{x_{i}}$. Let $\stackrel{\mbox{\scriptsize{$\bullet$}}}{}=(\stackrel{\mbox{\scriptsize{$\bullet$}}}{}_{i})_{1\le i\le r}$ be the increasing sequence $\stackrel{\mbox{\scriptsize{$\bullet$}}}{}_{i}=d_{1}+\cdots+d_{i}$. Let $\Coh_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}}(X)$ be the moduli stack of partial chains of torsion coherent sheaves $0\subset \cQ_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}_{1}}\subset \cdots\subset \cQ_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}_{r-1}}\subset \cQ_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}_{r}}=\cQ$ such that $\cQ_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}_{i}}$ has length $\stackrel{\mbox{\scriptsize{$\bullet$}}}{}_{i}$. The map $\pi^{\Coh}_{d}$ then factorizes as
\begin{equation*}
\wt\Coh_{d}(X)\xr{\pi_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}}}\Coh_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}}(X)\xr{\nu_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}}}\Coh_{d}(X).
\end{equation*}
We have a Cartesian diagram
\begin{equation}\label{partial Spr Coh}
\source{higher-siegel-weil-unitary-nonsingular-terms}
\xymatrix{\wt\Coh_{d}(X)\ar[d]^{\pi_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}}}\ar[r]^-{\wt c} & \prod_{i=1}^{r} \wt\Coh_{d_{i}}\ar[d]^{\prod\pi^{\Coh}_{d_{i}}} \\
\Coh_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}}(X)\ar[r]^-{c} & \prod_{i=1}^{r}\Coh_{d_{i}}(X)}
\end{equation}
where $c$ sends $(\cQ_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}_{i}})$ to $(\cQ_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}_{i}}/\cQ_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}_{i-1}})$. By proper base change we have $R\pi_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}*}\Qlbar\cong c^{*}(\boxtimes_{i=1}^{r}\Spr_{d_{i}})$, and the latter carries the Springer action of $S_{d_{1}}\times\cdots\times S_{d_{r}}=S_{y_{0}}$ (pulled back along $c$). Pushing forward along $\nu_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}}$, this induces an action of $S_{y_{0}}$ on $R\nu_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}*}R\pi_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}*}\Qlbar=\Spr_{d}$. This action coincides with the restriction of the action of $S_{d}$ because both actions come from deck transformations over $\Coh_{d}(X)^{\c}$. 

Now $\nu_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}}^{-1}(\cQ)$ contains the point $\cQ^{\da}\in \Coh_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}}(X)$ where ${\rm supp}\,\cQ_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}_{i}}/\cQ_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}_{i-1}}=\{x_{i}\}$ for $1\le i\le r$. This is an isolated point in $\nu^{-1}_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}}(\cQ)$, and $\cB_{\cQ}(y_{0})=\pi_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}}^{-1}(\cQ^{\da})$.   Moreover, the isomorphism \eqref{BQy} is the one given by taking the Cartesian diagram \eqref{partial Spr Coh} and restricting to $\cQ^{\da}\in \Coh_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}}(X)$. The above discussion shows that the action of $S_{y_{0}}\subset S_{d}$ on $\cohog{*}{\cB_{\cQ}(y_{0})}\subset \cohog{*}{\cB_{\cQ}}$ is the same as the Springer action of $\prod_{i}S_{d_{i}}$ on $\ot_{i}\cohog{*}{\cB_{\cQ_{x_{i}}}}$ via the isomorphism \eqref{BQy}.

\source{higher-siegel-weil-unitary-nonsingular-terms}
\label{p:St} 
\source{higher-siegel-weil-unitary-nonsingular-terms}
\begin{enumerate}
\item If $\cQ\in \Coh_{d}(X)(\ov k)$ is not semisimple, then the stalk of $\St_{d}$ at $\cQ$ is zero.
\item Let $\cQ=\textnormal{op}_{v\in |X|}k_v^{\textnormal{op} d_{v}}\in \Coh_{d}(X)(k)$ be semisimple. Then the stalk of  $\St_{d}$ at $\cQ$ is $1$-dimensional, and the geometric Frobenius $\gFrob$ acts on the stalk $\St_{d,\cQ}$ by the scalar
\begin{equation*}
\e(\cQ)\prod_{v\in {\rm supp}\,\cQ}q_{v}^{d_{v}(d_{v}-1)/2}
\end{equation*}
where $\e(\cQ)\in\{\pm1\}$ is the sign of Frobenius permuting the geometric points in the support of $\cQ$ counted with multiplicities (as a multi-set of cardinality $d$).
\end{enumerate}

