\source{higher-siegel-weil-unitary-nonsingular-terms}
 When $\nu$ is \'etale and $d$ is odd, $(X'_{d})^{\s}=\vn$ hence $\Herm_{d}(X'/X)=\vn$. 

In general, when $\nu$ is ramified over the points $R\subset X(\ov k)$, $(X'_{d})^{\s}$ has a decomposition into open and closed subschemes according to the parity of the multiplicities of the divisor at each point $x\in R$.

\source{higher-siegel-weil-unitary-nonsingular-terms}
\label{l:Herm A1} There is a canonical isomorphism
\source{higher-siegel-weil-unitary-nonsingular-terms}
\begin{eqnarray*}
\Herm_{d}({\mathbb A}^{1}_{\sqrt{t}}/{\mathbb A}^{1}_{t})\cong [\fro_{d}/\Og_{d}].

\end{eqnarray*}
Here $\Og_{d}$ denotes the orthogonal group on a $d$-dimensional nondegenerate quadratic space over $k$ and $\fro_{d}$ is its Lie algebra (the stack $[\fro_{d}/\Og_{d}]$ is independent of the quadratic form).

\source{higher-siegel-weil-unitary-nonsingular-terms}
\label{l:Herm local}
\source{higher-siegel-weil-unitary-nonsingular-terms}
\begin{enumerate}
\item Let $(U,f)$ be a $\s$-equivariant \'etale chart for $X'_{\ov k}$. Then the map $f^{\Herm}_{d}$ is \'etale when restricted to $\Herm_{d}(U'/U)^{f}$. 
\item Assume $\nu$ is ramified at at most one point (over $\ov k$). Then the stack $\Herm_{d}(X'/X)_{\ov k}$  is covered by $\Herm_{d}(U'/U)^{f}$ for various $\s$-equivariant \'etale charts $(U,f)$ of $X'_{\ov k}$. In particular,  $\Herm_{d}(X'/X)$ is \'etale locally isomorphic to  $[\fro_{d}/\Og_{d}]$.
\item In general, $\Herm_{d}(X'/X)$ is smooth of dimension $0$.
\end{enumerate}

\source{higher-siegel-weil-unitary-nonsingular-terms}
\label{p:SH Spr}
\source{higher-siegel-weil-unitary-nonsingular-terms}
\begin{enumerate}
\item If $\nu$ is ramified at at most one point, then the map $\pi^{\Herm}_{d}$ is \'etale locally isomorphic to the Grothendieck alteration $\pi_{\Og_{d}}:[\wt\fro_{d}/\Og_{d}]\to [\fro_{d}/\Og_{d}]$. 
\item In general, $\wt\Herm_{d}(X'/X)$ is smooth of dimension $0$ and $\pi^{\Herm}_{d}$ is a small map. In particular, the complex
\begin{equation*}
\Spr^{\Herm}_{d}:=R\pi^{\Herm}_{d,*}\Qlbar
\end{equation*}
is the middle extension perverse sheaf of its restriction to $\Herm_{d}(X'/X)^{\c}$.
\end{enumerate}


(1) The proof is similar to that of Corollary \ref{c:Coh Spr}. For a $\s$-equivariant \'etale chart $(U,f)$ for $X'_{\ov k}$ we have a diagram with Cartesian squares and \'etale horizontal maps by Lemma \ref{l:Herm local}
\begin{equation}\label{SH chart}
\source{higher-siegel-weil-unitary-nonsingular-terms}
\xymatrix{    \wt\Herm_{d}(X'/X)_{\ov k} \ar[d]^{\pi^{\Herm}_{d,X'/X}}& \wt\Herm_{d}(U'/U)^{f} \ar[r]\ar@{_{(}->}[l] \ar[d]^{\pi^{\Herm}_{d,U'/U}}& \wt\Herm_{d}({\mathbb A}^{1}_{\sqrt{t}}/{\mathbb A}^{1}_{t}\ar[d]^{\pi^{\Herm}_{d, {\mathbb A}^{1}_{\sqrt{t}}/{\mathbb A}^{1}_{t}}})_{\ov k}        \\
\Herm_{d}(X'/X)_{\ov k}    & \Herm_{d}(U'/U)^{f}\ar[r]^{f^{\Herm}_{d}}\ar@{_{(}->}[l] & \Herm_{d}({\mathbb A}^{1}_{\sqrt{t}}/{\mathbb A}^{1}_{t})_{\ov k}     }
\end{equation}
Using the isomorphism in Lemma \ref{l:Herm A1}, we identify $\pi^{\Herm}_{d, {\mathbb A}^{1}_{\sqrt{t}}/{\mathbb A}^{1}_{t}}$ with the Grothendieck alteration $\pi_{\Og_{d}}$.  Since $\Herm_{d}(U'/U)^{f}$ cover $\Herm_{d}(X'/X)$ by Lemma \ref{l:Herm local}(2), $\pi^{\Herm}_{d,X'/X}$ is 
\'etale locally  isomorphic to $\pi^{\Herm}_{d, {\mathbb A}^{1}_{\sqrt{t}}/{\mathbb A}^{1}_{t}}=\pi_{\Og_{d}}$.

(2) We use the notation from the proof of Lemma \ref{l:Herm local}(3). We may assume $|R|\ge2$. For each function $\stackrel{\mbox{\scriptsize{$\bullet$}}}{}: R\to {\mathbb Z}_{\ge0}$ satisfying $\sum_{x\in R}\stackrel{\mbox{\scriptsize{$\bullet$}}}{}(x)=d$, the base change of $\pi^{\Herm}_{d}$ along $\frY_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}}^{\hs}\to (X'_{d})^{\s}$ is a disjoint union of the restriction of
\begin{equation*}
\prod_{x}\pi^{\Herm}_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}(x)}: \prod_{x\in R}\wt\Herm_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}(x)}(Y'_{x}/Y_{x})\to \prod_{x\in R}\Herm_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}(x)}(Y'_{x}/Y_{x})
\end{equation*}
to $\frY_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}}^{\hs}$. The disjoint union comes from different ways to distribute ${\rm supp}\,(\cQ_{i}/\cQ_{i-1})$ among various factors in the product $\prod_{x}(Y'_{x,\stackrel{\mbox{\scriptsize{$\bullet$}}}{}(x)})^{\s}$. By (1), $\pi^{\Herm}_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}(x)}: \wt\Herm_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}(x)}(Y'_{x}/Y_{x})\to \Herm_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}(x)}(Y'_{x}/Y_{x})$ has smooth $0$-dimensional source and is small for each $x\in R$, the same holds true for the base change of $\pi^{\Herm}_{d}$ to $\frY_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}}^{\hs}$. Since $\{\frY_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}}^{\hs}\}_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}}$ form an \'etale covering of $(X'_{d})^{\s}$, the same is true for $\pi^{\Herm}_{d}$.

\begin{equation}\label{SH chart}
\source{higher-siegel-weil-unitary-nonsingular-terms}
\xymatrix{    \wt\Herm_{d}(X'/X)_{\ov k} \ar[d]^{\pi^{\Herm}_{d,X'/X}}& \wt\Herm_{d}(U'/U)^{f} \ar[r]\ar@{_{(}->}[l] \ar[d]^{\pi^{\Herm}_{d,U'/U}}& \wt\Herm_{d}({\mathbb A}^{1}_{\sqrt{t}}/{\mathbb A}^{1}_{t}\ar[d]^{\pi^{\Herm}_{d, {\mathbb A}^{1}_{\sqrt{t}}/{\mathbb A}^{1}_{t}}})_{\ov k}        \\
\Herm_{d}(X'/X)_{\ov k}    & \Herm_{d}(U'/U)^{f}\ar[r]^{f^{\Herm}_{d}}\ar@{_{(}->}[l] & \Herm_{d}({\mathbb A}^{1}_{\sqrt{t}}/{\mathbb A}^{1}_{t})_{\ov k}     }
\end{equation}

Let
\begin{equation*}
W_{d}:=({\mathbb Z}/2{\mathbb Z})^{d}\rtimes S_{d}
\end{equation*}
be the Weyl group for $\Og_{2d}$.

\source{higher-siegel-weil-unitary-nonsingular-terms}
\label{c:Wd action} If $\nu:X'\to X$ is an \'etale double cover, then there is a canonical action of $W_{d}$ on $\Spr^{\Herm}_{2d}$ extending the geometric action on its restriction to $\Herm_{2d}(X'/X)^{\c}$.
\source{higher-siegel-weil-unitary-nonsingular-terms}

\source{higher-siegel-weil-unitary-nonsingular-terms}
\label{l:permute comp}
\source{higher-siegel-weil-unitary-nonsingular-terms}
The action of $w\in W_{d}$ on $\cohog{*}{\cB^{\Herm}_{\cQ}}$ sends the direct summand $\cohog{*}{\cB^{\Herm}_{\cQ}(y')}$ to the direct summand $\cohog{*}{\cB^{\Herm}_{\cQ}(y'\c w^{-1})}$.

It suffices to check the statement for each simple reflection $s_{i}$, $i=1,\cdots, d$. Here, for $1\le i\le d-1$,  $s_{i}=(i,i+1)(2d-i,2d+1-i)$; for $i=d$, $s_{d}=(d,d+1)$. For $1\le i\le d$, let $\wt\Herm^{i}_{2d}$ be the moduli stack classifying isotropic flags that only misses the terms $\cQ_{i}$ and $\cQ_{2d-i}$ (for $i=d$ only misses $\cQ_{d}$). Then we have a factorization
\begin{equation*}
\pi^{\Herm}_{2d}: \wt\Herm_{2d}\xr{\r_{i}}\wt\Herm^{i}_{2d}\xr{\pi_{i}}\Herm_{2d}.
\end{equation*}
The map $\r_{i}$ is an \'etale double cover over the open dense locus  $\wt\Herm^{i,\hs}_{2d}$  where $\cQ_{i+1}/\cQ_{i-1}$ (which has length $2$) is supported at two distinct points. The map $\r_{i}$ is small, and $R\r_{i*}\Qlbar$ carries an involution $\wt s_{i}$, which induces an involution $\wt s_{i}$ on $R\pi_{i*}R\r_{i*}\Qlbar\cong R\pi^{\Herm}_{2d*}\Qlbar$. This action coincides with the action of $s_{i}$ over $\Herm_{2d}^{\c}$, hence coincides with $s_{i}$ everywhere. 

Let $(\cQ,h)\in\Herm_{2d}(\ov k)$, and $\cB_{\cQ}^{i}=\pi_{i}^{-1}(\cQ,h)$. We have a decomposition of $\cB_{\cQ}^{i}$ by the orbit set $\Sigma(Z')/\j{s_{i}}$. When $y'\in\Sigma(Z')$ satisfies $y'\ne y'\c s_{i}$, the $s_{i}$-orbit of $\y'=\{y',y'\c s_{i}\}$ gives an open closed substack $\cB^{i}_{\cQ}(\y')\subset \cB_{\cQ}^{i}$, such that $\r^{-1}_{i}(\cB^{i}_{\cQ}(\y'))=\cB_{\cQ}(y')\coprod\cB_{\cQ}(y'\c s_{i})$, and $\cB^{i}_{\cQ}(\y')\subset \wt\Herm^{i,\hs}_{2d}$. Therefore in this case the action of $\wt s_{i}$ on $\cohog{*}{\r^{-1}_{i}(\cB^{i}_{\cQ}(\y'))}$ comes from the involution on $\cB_{\cQ}(y')\coprod\cB_{\cQ}(y'\c s_{i})$ that interchanges the two components. Since $\wt s_{i}=s_{i}$, this proves the statement for $s_{i}$ and $y'$ such that $y'\ne y'\c s_{i}$. For $y'=y'\c s_{i}$ the statement is vacuous. This finishes the proof.

\source{higher-siegel-weil-unitary-nonsingular-terms}
\label{l:min w Herm}
\source{higher-siegel-weil-unitary-nonsingular-terms}
Let $y',y''\in \Sig(Z')$ and let $w\in W_{d}$ be a minimal length element such that $y''=y'\c w^{-1}$. Then the Springer action $w: \cohog{*}{\cB^{\Herm}_{\cQ}(y')}\to  \cohog{*}{\cB^{\Herm}_{\cQ}(y'')}$ is induced by the isomorphism $\g_{y', y''}$.

\source{higher-siegel-weil-unitary-nonsingular-terms}
\label{p:Spr HSpr}
\source{higher-siegel-weil-unitary-nonsingular-terms}
There is a canonical $S_{d}$-equivariant isomorphism of perverse sheaves on $\Lagr^{\dm}_{2d}$
\begin{equation*}
\upsilon^{\dm,*}_{2d}\HSpr_{d}\cong \e^{\dm,*}_{d}\Spr_{d}.
\end{equation*}

 The map $\pi^{\Herm}_{2d}$ factors as
\begin{equation*}
\pi^{\Herm}_{2d}: \wt\Herm_{2d}\xr{\l_{2d}} \Lagr_{2d}\xr{\upsilon_{2d}} \Herm_{2d}.
\end{equation*}
Let $\l^{\dm}_{2d}: \wt\Herm^{\dm}_{2d}\to \Lagr^{\dm}_{2d}$ be the restriction of $\l_{2d}$ to $\Lagr^{\dm}_{2d}$.
We have a commutative diagram
\begin{equation}\label{3sq}
\source{higher-siegel-weil-unitary-nonsingular-terms}
\xymatrix{\Herm_{2d}\times_{X_{d}}X^{d}\ar[d] & \wt\Herm^{\dm}_{2d}\ar[l]\ar[dl]_{\pi^{\Herm,\dm}_{2d}}\ar[d]^{\l^{\dm}_{2d}}\ar[r]^-{\wt \e'^{\dm}_{d}} & \wt\Coh_{d}(X')^{\dm}\ar[d]^{\pi^{\Coh,\dm}_{X',d}}\ar[r]^{\nu_{*}} &\wt\Coh_{d}(X)\ar[d]^{\pi^{\Coh}_{d}} \\
\Herm_{2d} & \Lagr^{\dm}_{2d}\ar@/_2pc/[rr]^-{\e^{\dm}_{d}}\ar[l]_{\upsilon^{\dm}_{2d}}\ar[r]^-{\e'^{\dm}_{d}} & \Coh_{d}(X')^{\dm}\ar[r]^{\nu_{*}} &   \Coh_{d}(X)
}
\end{equation}
Here $\Coh_{d}(X')^{\dm}$ and $\wt\Coh_{d}(X')^{\dm}$ are the preimages of $(X'_{d})^{\dm}$ under the support map.  We have:
\begin{itemize}
\item The middle square is Cartesian. This is true even before restricting to the $\dm$ locus. 
\item Since $\e'^{\dm}_{d}$  is an isomorphism, so is $\wt \e'^{\dm}_{d}$.
\item The rightmost square is Cartesian. 
\end{itemize}
From these properties we get maps
\begin{eqnarray*}
\a: \upsilon^{\dm *}_{2d}\HSpr_{d} &\to& \upsilon^{\dm*}_{2d}\Spr^{\Herm}_{2d}=\upsilon^{\dm*}_{2d}R\upsilon_{2d*}R\l_{2d*}\Qlbar\to \upsilon^{\dm*}_{2d}R\upsilon^{\dm}_{2d*}R\l^{\dm}_{2d*}\Qlbar \\
&\to&  R\l^{\dm}_{2d*}\Qlbar\cong \e^{\dm*}_{d}\pi^{\Coh}_{d*}\Qlbar=\e^{\dm*}_{d}\Spr_{d}.
\end{eqnarray*}



To check $\a$ is an isomorphism, it suffices to check on geometric stalks. Let $\cL\in \Coh_{d}(X')^{\dm}(\ov k)$ with support $Z^{\sh}\subset X'(\ov k)$. Let $\cQ=\cL\textnormal{op} \s^{*}\cL^{\vee}\in \Herm_{2d}(\ov k)$. The support of $\cQ$ is $Z'=Z^{\sh}\coprod \s(Z^{\sh})$, with image $Z\subset X(\ov k)$. We have $(\cL\subset \cQ)\in \Lagr^{\dm}_{2d}(\ov k)$, with image $\nu_{*}\cL\in\Coh_{d}(X)(\ov k)$. The stalk of $\a$ at $(\cL\subset\cQ)$ is
\begin{equation}\label{astalk}
\source{higher-siegel-weil-unitary-nonsingular-terms}
\a_{(\cL\subset\cQ)}: \cohog{*}{\cB^{\Herm}_{\cQ}}^{({\mathbb Z}/2{\mathbb Z})^{d}}\to\cohog{*}{\l^{-1}_{2d}(\cL\subset\cQ)}\stackrel{\sim}{\longrightarrow} \cohog{*}{\cB_{\nu_{*}\cL}}
\end{equation}
Recall $\cB^{\Herm}_{\cQ}=\coprod_{y'\in\Sig(Z')}\cB^{\Herm}_{\cQ}(y')$. Let $\Sig(Z^{\sh})\subset \Sig(Z')$ be the set of $y'$ such that $y'(i)\in Z^{\sh}$ for $1\le i\le d$. Then we have a natural bijection $\Sig(Z)\bij\Sig(Z^{\sh}), y\mapsto y^{\sh}$. The fiber $\l^{-1}_{2d}(\cL\subset\cQ)$ is the disjoint union $\coprod_{y\in\Sig(Z)}\cB^{\Herm}_{\cQ}(y^{\sh})$. Recall the isomorphism $\g_{Z^{\sh}, y^{\sh}}:  \cB^{\Herm}_{\cQ}(y^{\sh})\stackrel{\sim}{\longrightarrow}  \cB_{\nu_{*}\cL}(y)$ from \eqref{gZ}. Using these descriptions we may rewrite \eqref{astalk} as
\begin{equation}
\cohog{*}{\cB^{\Herm}_{\cQ}}^{({\mathbb Z}/2{\mathbb Z})^{d}}  \twoheadrightarrow \textnormal{op}_{y'\in\Sig(Z^{\sh})}\cohog{*}{\cB^{\Herm}_{\cQ}(y')}\cong \textnormal{op}_{y\in \Sig(Z)}\cohog{*}{\cB_{\nu_{*}\cL}(y)}=\cohog{*}{\cB_{\nu_{*}\cL}}.
\end{equation}
It remains to show that the first map above is an isomorphism. But this follows from the fact that  $({\mathbb Z}/2{\mathbb Z})^{d}$ acts freely on $\Sig(Z')$ with orbit representatives $\Sig(Z^{\sh})$, and Lemma \ref{l:permute comp}. This shows that $\a$ is an isomorphism. 


Finally we show that $\a$ is $S_{d}$-equivariant. By Proposition  \ref{p:SH Spr}, $\pi^{\Herm}_{2d}$ and hence $\l_{2d}$ is small,  $R\l_{2d*}\Qlbar$ is the middle extension from a dense open substack of $\Lagr_{2d}$. Therefore the same is true for $R\l^{\dm}_{2d*}\Qlbar$. Since $\a$ is an isomorphism, both $\upsilon^{\dm,*}_{2d}\HSpr_{d}$ and $\e^{\dm*}_{d}\Spr_{d}$ are middle extension perverse sheaves from a dense open substack of $\Lagr^{\dm}_{2d}$. To check that $\a$ is $S_{d}$-equivariant it suffices to check it over the dense open substack which is the preimage of the multiplicity-free locus $X_{d}^{\c}$. Over $X_{d}^{\c}$, all squares in \eqref{3sq} are Cartesian,  and all vertical maps are $S_{d}$-torsors. The $S_{d}$-actions on $\HSpr_{d}|_{\Herm_{2d}^{\c}}$ and $\Spr_{d}|_{\Coh_{d}(X)^{\c}}$ come from the vertical $S_{d}$-torsors in the diagram, so $\a$ is $S_{d}$-equivariant when restricted over $X_{d}^{\c}$. This finishes the proof.

\source{higher-siegel-weil-unitary-nonsingular-terms}
\label{l:bij}
\source{higher-siegel-weil-unitary-nonsingular-terms}
There is a canonical bijection of sets
\begin{equation*}
|\Herm_{2d}(X'/X)(k)|\cong |\Coh_{d}(X)(k)|

\end{equation*}
respecting the support maps to $X_{d}(k)$.

\source{higher-siegel-weil-unitary-nonsingular-terms}
\label{p:trace relation}  Let $\th$ be the involution on $\cohog{*}{\cB_{\cQ^{\flat}}}$ which is $1$ on $\cohog{*}{\cB_{\cQ^{\flat}}}^{+}$ and $-1$ on $\cohog{*}{\cB_{\cQ^{\flat}}}^{-}$. Then under the isomorphism $\a^{\sh}$, $\gFrob_{\cQ}$ corresponds to $\gFrob_{\cQ^{\flat}}\c\th$.
\source{higher-siegel-weil-unitary-nonsingular-terms}

 Recall from the proof of Proposition \ref{p:Spr HSpr} that $\a^{\sh}$ is the composition
\begin{equation*}
\cohog{*}{\cB_{\cQ}^{\Herm}}^{({\mathbb Z}/2{\mathbb Z})^{d}}\cong \bigoplus_{y\in \Sig(Z)}\cohog{*}{\cB^{\Herm}_{\cQ}(y^{\sh})}\xr{\textnormal{op}\g_{Z^{\sh}, y^{\sh}}}\bigoplus_{y\in \Sig(Z)}\cohog{*}{\cB_{\cQ^{\flat}}(y)}.
\end{equation*}
Here $\g_{Z^{\sh},y^{\sh}}$ is defined in \eqref{gZ}.


Then $\Fr^{*}$ on $\cohog{*}{\cB^{\Herm}_{\cQ}}$ maps $\cohog{*}{\cB^{\Herm}_{\cQ}(\Fr(y^{\sh}))}$ to $\cohog{*}{\cB^{\Herm}_{\cQ}(y^{\sh})}$. Note that $\Fr(y^{\sh})$ and $(\Fr y)^{\sh}$ are in general different: if $y(i)=\Fr^{-1}(x_{v})$ for some inert  $v$, then $\Fr(y^{\sh})(i)=\s(x'_{v})$ while $(\Fr y)^{\sh}(i)=x'_{v}$. In other words, the only difference between $\Fr (y^{\sh})$ and $(\Fr y)^{\sh}$ is the switch of all $x'_{v}$ and $\s(x'_{v})$ for all inert $v$. Therefore there is a unique element $\t_{y}\in({\mathbb Z}/2{\mathbb Z})^{d}$ such that $(\Fr y)^{\sh}=\Fr (y^{\sh})\c \t_{y}$.

Identifying $\cohog{*}{\cB_{\cQ}^{\Herm}}^{({\mathbb Z}/2{\mathbb Z})^{d}}$ with $\textnormal{op}_{y\in \Sig(Z)}\cohog{*}{\cB_{\cQ}^{\Herm}(y^{\sh})}$, the geometric Frobenius endomorphism $\gFrob_{\cQ}$ on $\cohog{*}{\cB_{\cQ}^{\Herm}}^{({\mathbb Z}/2{\mathbb Z})^{d}}$ is the direct sum of the following compositions
\begin{equation*}
\cohog{*}{\cB_{\cQ}^{\Herm}((\Fr y)^{\sh})}\xr{\t_{y}}\cohog{*}{\cB_{\cQ}^{\Herm}(\Fr (y^{\sh}))} \xr{\Fr^{*}}\cohog{*}{\cB_{\cQ}^{\Herm}(y^{\sh})}
\end{equation*}
where the first map is the Springer action of $\t_{y}\in W_{d}$ on $(\Spr^{\Herm}_{2d})_{\cQ}$.

On the other hand, let $w_{y}\in W_{d}$ be the {\em minimal length} element such that $(\Fr y)^{\sh}= \Fr(y^{\sh})\c w_{y}$. Write
\begin{equation*}
\t_{y}=w_{y}u_{y}, \mbox{ for a unique } u_{y}\in {\mathrm{Stab}}_{W_{d}}((\Fr y)^{\sh})={\mathrm{Stab}}_{S_{d}}(\Fr y)\subset S_{d}.
\end{equation*}
Note that ${\mathrm{Stab}}_{S_{d}}(Fy)=\prod_{x\in Z}S_{I_{x}}$ where $I_{x}\subset \{1,2,\cdots, d\}$ is the preimage of $x$ under $y$. An easy calculation shows that $u_{y}=(u_{y,x})_{x\in Z}$ where  $u_{y,x}\in S_{I_{x}}$ is 
\begin{equation*}
u_{y,x}=\begin{cases} w_{I_{x}}, & \mbox{ if }x=x_{v}, v\in |Z|_{i},\\ 1, & \mbox{ otherwise.}\end{cases}
\end{equation*}
Here $w_{I_{x}}\in S_{I_{x}}$ is the involution that reverses the order of $I_{x}$. 


We use abbreviated notation
\begin{align*}
H(y') &:=\cohog{*}{\cB^{\Herm}_{\cQ}(y')}, \mbox{ for $y'\in\Sig(Z')$},\\
C(y) &:=\cohog{*}{\cB_{\cQ^{\flat}}(y)}, \mbox{ for $y\in\Sig(Z)$}.
\end{align*}
For each $y\in \Sig(Z)$, consider the following diagram
\begin{equation}\label{HC}
\source{higher-siegel-weil-unitary-nonsingular-terms}
\xymatrix{H((\Fr y)^{\sh})\ar[r]^{u_{y}}\ar[d]^{\g_{Z^{\sh}, (\Fr y)^{\sh}}} & H((\Fr y)^{\sh})\ar[rr]^-{w_{y}}\ar[d]^{\g_{Z^{\sh}, (\Fr y)^{\sh}}} & & H(\Fr (y^{\sh})) \ar[dll]^{\g_{Z^{\sh}, \Fr (y^{\sh})}}\ar[r]^{\Fr ^{*}}\ar[d]^{\g_{\Fr (Z^{\sh}), \Fr (y^{\sh})}} & H(y^{\sh})\ar[d]^{\g_{Z^{\sh}, y^{\sh}}}\\
C(Fy)\ar[r]^{u_{y}} & C(Fy)\ar[rr]^{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}^{*}} && C(Fy)\ar[r]^{\Fr^{*}} & C(y)}
\end{equation}
The left square is commutative by the $S_{d}$-equivariance of $\a^{\sh}$ proved in Proposition \ref{p:Spr HSpr} (here $u_{y}\in {\mathrm{Stab}}_{W_{d}}((\Fr y)^{\sh})\subset S_{d}$). The middle upper triangle is commutative by Lemma \ref{l:min w Herm}. The map $\stackrel{\mbox{\scriptsize{$\bullet$}}}{}^{*}$ is defined to make the lower middle triangle commutative. The right square is clearly commutative.  The composite of the upper row is the restriction of $\tn{Frob}_{\cQ}$ to $H((\Fr y)^{\sh})$. Let us compute the composite of the lower row. 

The map $\stackrel{\mbox{\scriptsize{$\bullet$}}}{}^{*}$ is the pullback along the automorphism $\stackrel{\mbox{\scriptsize{$\bullet$}}}{}$ of $\cB_{\cQ^{\flat}}(\Fr y)$ that makes the following diagram commutative
\begin{equation*}
\xymatrix{& \cB^{\Herm}_{\cQ}(\Fr (y^{\sh})) \ar[d]^{\g_{\Fr(Z^{\sh}), \Fr(y^{\sh})}}\ar[dl]_{\g_{Z^{\sh}, \Fr(y^{\sh})}}\\
\cB_{\cQ^{\flat}}(\Fr y) & \cB_{\cQ^{\flat}}(\Fr y) \ar[l]_{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}}}
\end{equation*}
Under the isomorphism $\b_{\Fr y}:\cB_{\cQ^{\flat}}(\Fr y)\stackrel{\sim}{\longrightarrow} \prod_{x\in Z}\cB_{\cQ^{\flat}_{x}}$, $\stackrel{\mbox{\scriptsize{$\bullet$}}}{}$ is the product of automorphisms $\stackrel{\mbox{\scriptsize{$\bullet$}}}{}_{x}$ for each $\cB_{\cQ^{\flat}_{x}}$. If $x$ is not of the form $x=x_{v}$ for $v\in |Z|_{i}$, 
$\stackrel{\mbox{\scriptsize{$\bullet$}}}{}_{x}$ is the identity. If $x=x_{v}$ for some $v\in |Z|_{i}$, then $\cQ^{\flat}_{x}=\cQ_{x'_{v}}$ and the Hermitian structure on $\cQ$ gives an isomorphism $\io: \cQ_{\s(x'_{v})}\cong\cQ_{x'_{v}}^{\vee}$. On the other hand, $\Fr^{\deg(v)}$ gives an isomorphism $\phi: \cQ_{x'_{v}}\cong \cQ_{\s(x'_{v})}$ since $\s(x'_{v})=\Fr^{\deg(v)}(x'_{v})$.  Combining $\io$ and $\phi$ we get a perfect symmetric pairing $(\cdot,\cdot)_{x'_{v}}$ on $\cQ_{x'_{v}}$ itself. Then $\stackrel{\mbox{\scriptsize{$\bullet$}}}{}_{x}$ sends a full flag $\cR_{\bu}$ of $\cQ^{\flat}_{x_{v}}=\cQ_{x'_{v}}$ to $\cR^{\bot}_{\bu}$ under the pairing $(\cdot,\cdot)_{x'_{v}}$.

By the description of $u_{y}$ and $\stackrel{\mbox{\scriptsize{$\bullet$}}}{}$ above, under the isomorphism $\b_{Fy}$, the composition $\stackrel{\mbox{\scriptsize{$\bullet$}}}{}^{*}\c u_{y}$ takes the form
\begin{equation*}
\ot(\stackrel{\mbox{\scriptsize{$\bullet$}}}{}_{x}^{*}\c u_{y,x}): \bigotimes_{x\in Z}\cohog{*}{\cB_{\cQ^{\flat}_{x}}}\to\bigotimes_{x\in Z}\cohog{*}{\cB_{\cQ^{\flat}_{x}}}.
\end{equation*}
The automorphisms $\stackrel{\mbox{\scriptsize{$\bullet$}}}{}_{x}^{*}\c u_{y,x}$ are the identity maps except when $x=x_{v}$ for some $v\in |Z|_{i}$, in which case $u_{y,x}=w_{I_{x}}$. Let us compute $\stackrel{\mbox{\scriptsize{$\bullet$}}}{}_{x}^{*}\c w_{I_{x}}$ on $\cohog{*}{\cB_{\cQ^{\flat}_{x}}}$ for $x=x_{v}$ and $v\in |Z|_{i}$.  For this we switch to the following notation. Let $V=\cQ_{x'_{v}}=\cQ^{\flat}_{x_{v}}$, a vector space of dimension $m$ over $\ov k$. We have argued that $V$ carries a symmetric self-duality $(\cdot,\cdot)$; the action of a uniformizer at $x_{v}$ gives a nilpotent element $e\in {\rm End}_{\ov k}(V)$, which is self-adjoint under $(\cdot,\cdot)$. Let $\cB$ be the flag variety of ${\rm GL}\,(V)$ and $\cB_{e}$ be the Springer fiber of $e$. Then $S_{m}$ acts on $\cohog{*}{\cB_{e}}$. Let $w_{0}$ be the longest element in $S_{m}$. Let $\stackrel{\mbox{\scriptsize{$\bullet$}}}{}: \cB_{e}\stackrel{\sim}{\longrightarrow} \cB_{e}$ be the map sending a flag $V_{\bu}$ to $V_{\bu}^{\bot}$. We claim that $\stackrel{\mbox{\scriptsize{$\bullet$}}}{}^{*}\c w_{0}$ acts on $\cohog{2i}{\cB_{e}}$ by $(-1)^{i}$. Indeed, by \cite[Corollary 2.3(2)]{HS77}, the restriction map $\cohog{*}{\cB}\to \cohog{*}{\cB_{e}}$ is surjective and is clearly equivariant under $\stackrel{\mbox{\scriptsize{$\bullet$}}}{}^{*}\c w_{0}$, so it suffices to show that $\stackrel{\mbox{\scriptsize{$\bullet$}}}{}^{*}\c w_{0}$ acts by $(-1)^{i}$ on $\cohog{2i}{\cB}$. Since $\stackrel{\mbox{\scriptsize{$\bullet$}}}{}^{*}\c w_{0}$ preserves the cup product on $\cohog{*}{\cB}$, it suffices to show it acts by $-1$ on $\cohog{2}{\cB}$ (which generates all of $\cohog{2*}{\cB}$ under the cup product). For $1\le j\le m$, let $\xi_{j}$ be  the Chern class of the tautological line bundle on $\cB$ whose fiber at $V_{\bu}$ is  $V_j/V_{j-1}$. Then $\cohog{2}{\cB}$ is spanned by $\xi_j$ for $1\le j\le m$. Now we have $w_{0}(\xi_{j})=\xi_{m+1-j}$ since $\cohog{2}{\cB}$ is the reflection representation of $S_{m}$, and $\stackrel{\mbox{\scriptsize{$\bullet$}}}{}^{*}\xi_{j}=-\xi_{m+1-j}$ by the definition of $\stackrel{\mbox{\scriptsize{$\bullet$}}}{}$. Therefore $\stackrel{\mbox{\scriptsize{$\bullet$}}}{}^{*}\c w_{0}(\xi_{j})=-\xi_{j}$ for all $1\le j\le m$, which proves that $\stackrel{\mbox{\scriptsize{$\bullet$}}}{}^{*}\c w_{0}$ acts by $-1$ on $\cohog{2}{\cB}$, and hence acts by $(-1)^{i}$ on $\cohog{2i}{\cB}$ and on $\cohog{2i}{\cB_{e}}$. 

The above argument shows that $\stackrel{\mbox{\scriptsize{$\bullet$}}}{}^{*}\c u_{y}$ acts by $1$ on $\cohog{*}{\cB_{\cQ^{\flat}}(\Fr y)}^{+}$ and acts by $-1$ on $\cohog{*}{\cB_{\cQ^{\flat}}(\Fr y)}^{-}$. Therefore the bottom row of \eqref{HC} is $\tn{Frob}_{\cQ^{\flat}}\c\th$. By the commutativity of \eqref{HC}, $\tn{Frob}_{\cQ^{\flat}}\c\th$ corresponds under $\a^{\sh}$ to the composite of the top row, which is $\tn{Frob}_{\cQ}$. This finishes the proof.

\begin{equation*}
\t_{y}=w_{y}u_{y}, \mbox{ for a unique } u_{y}\in {\mathrm{Stab}}_{W_{d}}((\Fr y)^{\sh})={\mathrm{Stab}}_{S_{d}}(\Fr y)\subset S_{d}.
\end{equation*}

\begin{equation}\label{HC}
\source{higher-siegel-weil-unitary-nonsingular-terms}
\xymatrix{H((\Fr y)^{\sh})\ar[r]^{u_{y}}\ar[d]^{\g_{Z^{\sh}, (\Fr y)^{\sh}}} & H((\Fr y)^{\sh})\ar[rr]^-{w_{y}}\ar[d]^{\g_{Z^{\sh}, (\Fr y)^{\sh}}} & & H(\Fr (y^{\sh})) \ar[dll]^{\g_{Z^{\sh}, \Fr (y^{\sh})}}\ar[r]^{\Fr ^{*}}\ar[d]^{\g_{\Fr (Z^{\sh}), \Fr (y^{\sh})}} & H(y^{\sh})\ar[d]^{\g_{Z^{\sh}, y^{\sh}}}\\
C(Fy)\ar[r]^{u_{y}} & C(Fy)\ar[rr]^{\stackrel{\mbox{\scriptsize{$\bullet$}}}{}^{*}} && C(Fy)\ar[r]^{\Fr^{*}} & C(y)}
\end{equation}

