\source{higher-siegel-weil-unitary-nonsingular-terms}
\label{th:Eis Den torsion} Let $\cE$ be a rank $n$ vector bundle over $X'$ and $a:\cE\hookrightarrow\s^{*}\cE^{\vee}$ be an injective Hermitian map. Then
\source{higher-siegel-weil-unitary-nonsingular-terms}
\[
E_{a}(m(\cE),s,\Phi)=\chi(\det(\cE))q^{-\deg(\cE)( s-n/2)-\frac{1}{2}n^2\deg(\omega_X) }
\times {\mathcal L}_n(s) ^{-1} \Den(q^{-2s}, {\rm coker}\,(a)).
\]

\source{higher-siegel-weil-unitary-nonsingular-terms}
\label{th:Den Wd} For any $\cQ\in \Herm_{2d}(k)$, we have
\source{higher-siegel-weil-unitary-nonsingular-terms}
\begin{equation*}
\Den(T,\cQ)={\rm Tr}(\tn{Frob}, \cK^{\Eis}_{d}(T)_{\cQ}).
\end{equation*}

By the Grothendieck-Lefschetz trace formula, we have
\begin{equation*}
{\rm Tr}(\tn{Frob}, \cK^{\Eis}_{d}(T)_{\cQ})= \sum_{i=0}^d \sum_{(\cI,\cQ)\in \Herm_{i,2d}(k)}T^{\dim_{k}\cI}{\rm Tr}(\tn{Frob}, \frP_{d-i}(T)_{\cI^{\bot}/\cI}).
\end{equation*}
Comparing with the expansion \eqref{Den sum} for $\Den(T,\cQ)$, it suffices to prove, changing notation $d-i$ to $d$ and $\cI^{\bot}/\cI$ to $\cQ$, that
\begin{equation}\label{Pm}
\source{higher-siegel-weil-unitary-nonsingular-terms}
{\rm Tr}(\tn{Frob}, \frP_{d}(T)_{\cQ})=\prod_{v\in |X|}\mathfrak m_{v}(t'_{v}(\cQ);T^{\deg(v)}).
\end{equation}
This will be proved in Proposition \ref{p:PQ trace}.

Define the Frobenius traces 
\begin{equation*}
P_{\cQ}(T):={\rm Tr}(\tn{Frob},\frP_{\cQ}(T)), \quad  P_{\cQ^{\flat}}(T):={\rm Tr}(\tn{Frob},\frP_{\cQ^{\flat}}(T)) \in \Qlbar[T].

\source{higher-siegel-weil-unitary-nonsingular-terms}
\label{l:Spr factor}
\source{higher-siegel-weil-unitary-nonsingular-terms}
We have a natural isomorphism of graded $\tn{Frob}$-modules
\begin{equation*}
\frP_{\cQ^{\flat}}(T)\cong\bigot_{v\in |Z|}\frP_{\cQ^{\flat}_{v}}(T).
\end{equation*}
In particular,
\begin{equation*}
P_{\cQ^{\flat}}(T)=\prod_{v\in |Z|}P_{\cQ^{\flat}_{v}}(T).
\end{equation*}

Choose any $y\in \Sig(Z)$ and let $|y|$ be the resulting map $\{1,2,\cdots, d\}\to |Z|$. Let $S_{|y|}={\mathrm{Stab}}_{S_{d}}(|y|)$, then $S_{|y|}\cong \prod_{v\in|Z|}S_{I_{v}}$, where $I_{v}=|y|^{-1}(v)$. Applying  Corollary \ref{c:Sind} to $\cQ^{\flat}$ and to each $\cQ^{\flat}_{v}$ gives an isomorphism of $(S_{d},\tn{Frob})$-modules 
\begin{equation}\label{HBQflat ind}
\source{higher-siegel-weil-unitary-nonsingular-terms}
\cohog{*}{\cB_{\cQ^{\flat}}}\cong \Ind^{S_{d}}_{S_{|y|}}\left(\bigot_{v\in|Z|}\cohog{*}{\cB_{\cQ^{\flat}_{v}}}\right).
\end{equation}
Here the factor $S_{I_{v}}$ of $S_{|y|}$ acts on $\cohog{*}{\cB_{\cQ^{\flat}_{v}}}$ by the Springer action. 

Write $H_{v}=\cohog{*}{\cB_{\cQ^{\flat}_{v}}}$ as a $(S_{I_{v}},\tn{Frob})$-module. Let $d_{v}=\# I_{v}$. By Mackey theory, the $(S_{j}\times S_{d-j}, \sgn_{j}\bt1)$-isotypical part of the right side of \eqref{HBQflat ind} is a direct sum over double cosets $(S_{j}\times S_{d-j})\bs S_{d}/S_{|y|}$, which can be identified with the set of functions $i: |Z|\to {\mathbb Z}_{\ge0}$, $v\mapsto i_{v}\le d_{v}$, such that $\sum_{v}i_{v}=j$. The stabilizer of the $S_{j}\times S_{d-j}$-action on the orbit indexed by $i$ is isomorphic to $\prod_{v\in |Z|}S_{i_{v}}\times S_{d_{v}-i_{v}}$ (where the $S_{i_{v}}$ factor lies in $S_{j}$, $S_{d_{v}-i_{v}}$ lies in $S_{d-j}$, and $S_{i_{v}}\times S_{d_{v}-i_{v}}$ is naturally a subgroup of $S_{I_{v}}\cong S_{d_{v}}$). The contribution of the summand indexed by $i$ is 
\begin{equation*}
\bigot_{v\in |Z|}H_{v}^{(S_{i_{v}}\times S_{d_{v}-i_{v}}, \sgn_{i_{v}}\bt 1)}.
\end{equation*}
This implies that
\begin{eqnarray*}
\frP_{\cQ^{\flat}}(T)&\cong &\sum_{i:|Z|\to {\mathbb Z}_{\ge0},  i_{v}\le d_{v}}(-1)^{\sum i_{v}}\left(\bigot_{v\in |Z|} H_{v}^{(S_{i_{v}}\times S_{d_{v}-i_{v}}, \sgn_{i_{v}}\bt 1)}\right)T^{\sum i_{v}}\\
&\cong&\bigot_{v\in |Z|}\left(\sum_{i_{v}=0}^{d_{v}} (-1)^{i_{v}}H_{v}^{(S_{i_{v}}\times S_{d_{v}-i_{v}}, \sgn_{i_{v}}\bt 1)}T^{i_{v}}\right) = \bigot_{v\in |Z|}\frP_{\cQ^{\flat}_{v}}(T).
\end{eqnarray*}

\begin{eqnarray*}
\frP_{\cQ^{\flat}}(T)&\cong &\sum_{i:|Z|\to {\mathbb Z}_{\ge0},  i_{v}\le d_{v}}(-1)^{\sum i_{v}}\left(\bigot_{v\in |Z|} H_{v}^{(S_{i_{v}}\times S_{d_{v}-i_{v}}, \sgn_{i_{v}}\bt 1)}\right)T^{\sum i_{v}}\\
&\cong&\bigot_{v\in |Z|}\left(\sum_{i_{v}=0}^{d_{v}} (-1)^{i_{v}}H_{v}^{(S_{i_{v}}\times S_{d_{v}-i_{v}}, \sgn_{i_{v}}\bt 1)}T^{i_{v}}\right) = \bigot_{v\in |Z|}\frP_{\cQ^{\flat}_{v}}(T).
\end{eqnarray*}

\source{higher-siegel-weil-unitary-nonsingular-terms}
\label{l:HSpr factor} Let $\cQ\in \Herm_{2d}(k)$.
\source{higher-siegel-weil-unitary-nonsingular-terms}
\begin{enumerate}
\item We have
\begin{equation}\label{HSpr factor}
\source{higher-siegel-weil-unitary-nonsingular-terms}
\frP_{\cQ}(T)\cong\bigot_{v\in |Z|}\frP_{\cQ_{v}}(T), \quad
P_{\cQ}(T)=\prod_{v\in |Z|}P_{\cQ_{v}}(T).
\end{equation}
\item If $v\in |Z|$ is split in $X'$, then
\begin{equation}\label{PQ split}
\source{higher-siegel-weil-unitary-nonsingular-terms}
P_{\cQ_{v}}(T)=P_{\cQ^{\flat}_{v}}(T).
\end{equation}
\item If $v\in |Z|$ is inert in $X'$, then
\begin{equation}\label{PQ inert}
\source{higher-siegel-weil-unitary-nonsingular-terms}
P_{\cQ_{v}}(T)=\sum_{i}(-1)^{i}{\rm Tr}(\tn{Frob},\Gr^{W}_{2i\deg(v)}\frP_{\cQ^{\flat}_{v}}(T)).
\end{equation}
Moreover, ${\rm Tr}(\tn{Frob},\Gr^{W}_{i}\frP_{\cQ^{\flat}_{v}}(T))=0$ if $i$ is not a multiple of $2\deg(v)$.
\end{enumerate}

 We will use the notations from \S\ref{sss:choose points}. For each $y\in \Sig(Z)$, the summand $\cohog{*}{\cB_{\cQ^{\flat}}(y)}\cong \ot_{x\in Z}\cohog{*}{\cB_{\cQ^{\flat}_{x}}}$ is graded by multidegree $\bi: Z\to {\mathbb Z}_{\ge0}$
\begin{equation*}
\cohog{2\bi}{\cB_{\cQ^{\flat}}(y)}=\bigot_{x\in Z}\cohog{2\bi(x)}{\cB_{\cQ^{\flat}_{x}}}.
\end{equation*}
We define $\cohog{2\bi}{\cB_{\cQ^{\flat}}}$ as the direct sum of  $\cohog{2\bi}{\cB_{\cQ^{\flat}}(y)}$ over all $y\in \Sig(Z)$. Then each $\cohog{2\bi}{\cB_{\cQ^{\flat}}}$ is stable under $S_{d}$. Accordingly, $\frP_{\cQ^{\flat}}(T)$ decomposes into the direct sum of $\frP^{2\bi}_{\cQ^{\flat}}(T)$, which is by definition $\textnormal{op}_{j=0}^{d}(-1)^{j}\cohog{2\bi}{\cB_{\cQ^{\flat}}}^{(S_{j}\times S_{d-j}, \sgn_{j}\bt1)}T^{j}$. Let $\bi_{v}$ be the restriction of $\bi$ to those $x|v$, then under the factorization isomorphism in Lemma \ref{l:Spr factor} we have
\begin{equation}\label{frPi}
\source{higher-siegel-weil-unitary-nonsingular-terms}
\frP^{2\bi}_{\cQ^{\flat}}(T)\cong \bigot_{v\in |Z|} \frP^{2\bi_{v}}_{\cQ^{\flat}_{v}}(T).
\end{equation}

(1) Recall the involution $\th$  on $\cohog{*}{\cB_{\cQ^{\flat}}}$ in Proposition \ref{p:trace relation}. Using the above notation,  we see that $\th$ acts on $\cohog{2\bi}{\cB_{\cQ^{\flat}}}$ by $\prod_{v\in |
Z|_{i}}(-1)^{\bi(x_{v})}$ (where $x_{v}\in Z$ is a chosen geometric point over $v$, as in \S\ref{sss:choose points}). Because of \eqref{frPi}, the action of $\th$ on $\frP_{\cQ^{\flat}}(T)$ factorizes as the tensor product of the similarly-defined $\th_{v}$ on each $\frP_{\cQ^{\flat}_{v}}(T)$. By Proposition \ref{p:trace relation}, $\frP_{\cQ}(T)$ is the Frobenius module obtained by modifying the Frobenius action on $\frP_{\cQ^{\flat}}(T)$ by composing with $\th$. By Lemma \ref{l:Spr factor}, this modified Frobenius structure on  $\frP_{\cQ^{\flat}}(T)$ is the tensor product of the similarly modified Frobenius modules $\frP_{\cQ^{\flat}_{v}}(T)$, which in turn are isomorphic to $\frP_{\cQ_{v}}(T)$ by Proposition \ref{p:trace relation}. This implies \eqref{HSpr factor}.

(2) From the definition we see that if $v$ is split, then $\th_{v}$ is the identity on $\frP_{\cQ^{\flat}_{v}}(T)$. Hence $\frP_{\cQ_{v}}(T)=\frP_{\cQ^{\flat}_{v}}(T)$ and $P_{\cQ_{v}}(T)=P_{\cQ^{\flat}_{v}}(T)$.

(3) Since the cohomology of $\cB_{\cQ^{\flat}_{v}}$ is pure by \cite[Corollary 2.3(3)]{HS77}, we see that $\Gr^{W}_{i}\frP_{\cQ^{\flat}_{v}}(T)$ is the sum of $\frP^{2\bi_{v}}_{\cQ^{\flat}_{v}}(T)$ where $\bi_{v}: \{x\in Z: x|v\}\to {\mathbb Z}_{\ge0}$ satisfies $\sum_{x|v}2\bi_{v}(x)=i$. The action of Frobenius sends $\frP^{2\bi_{v}}_{\cQ^{\flat}_{v}}(T)$ to $\frP^{2F^{*}\bi_{v}}_{\cQ^{\flat}_{v}}(T)$, where $F^{*}\bi_{v}$ means precomposing $\bi_{v}$ with Frobenius. Therefore only constant multi-degrees (i.e., constant functions $\bi_{v}$) contribute to the Frobenius trace of $\frP_{\cQ^{\flat}_{v}}(T)$. This implies ${\rm Tr}(\tn{Frob}, \Gr^{W}_{i}\frP_{\cQ^{\flat}_{v}}(T))=0$ unless $i$ is a multiple of $2\deg(v)$.

By the discussion above,
\begin{equation*}
P_{\cQ_{v}}(T)={\rm Tr}(\tn{Frob}\c\th_{v},  \frP_{\cQ^{\flat}_{v}}(T))=\sum_{i\ge0}{\rm Tr}(\tn{Frob}\c\th_{v}, \frP^{(2i,2i,\cdots,2i)}_{\cQ^{\flat}_{v}}(T)).
\end{equation*}
Since $v$ is inert, $\th_{v}$ acts by $(-1)^{i}$ on $\frP^{(2i,2i,\cdots,2i)}_{\cQ^{\flat}_{v}}(T)$, hence
\begin{equation*}
{\rm Tr}(\tn{Frob}\c\th_{v}, \frP^{(2i,2i,\cdots,2i)}_{\cQ^{\flat}_{v}}(T))=(-1)^{i}{\rm Tr}(\tn{Frob}, \frP^{(2i,2i,\cdots,2i)}_{\cQ^{\flat}_{v}}(T)).
\end{equation*}
On the other hand,  ${\rm Tr}(\tn{Frob}, \Gr^{W}_{2i\deg(v)}\frP_{\cQ^{\flat}_{v}}(T))$ is the sum of ${\rm Tr}(\tn{Frob}, \frP^{2\bi_{v}}_{\cQ^{\flat}_{v}}(T))$ with total degree $\sum_{x|v}2\bi_{v}(x)=2i\deg(v)$. Since only constant multi-degrees contribute to the trace, we again conclude
\begin{equation*}
{\rm Tr}(\tn{Frob}, \Gr^{W}_{2i\deg(v)}\frP_{\cQ^{\flat}_{v}}(T))={\rm Tr}(\tn{Frob}, \frP^{(2i,2i,\cdots,2i)}_{\cQ^{\flat}_{v}}(T)).
\end{equation*}
Combining the above identities we get \eqref{PQ inert}.

\source{higher-siegel-weil-unitary-nonsingular-terms}
\label{p:PQ Coh trace} For $\cQ^{\flat}\in \Coh_{d}(X)(k)$, we have
\source{higher-siegel-weil-unitary-nonsingular-terms}
\begin{equation*}
P_{\cQ^{\flat}}(T)=\prod_{v\in |Z|}(1-T^{\deg(v)})(1-q_{v}T^{\deg(v)})\cdots (1-q_{v}^{t_{v}(\cQ^{\flat})-1}T^{\deg(v)}).
\end{equation*}

 We write $\Coh_{d}(X)$ simply as $\Coh_{d}$ in the proof. For $0\le j\le d$, consider the correspondence
\begin{equation*}
\xymatrix{ & \Coh_{j,d}\ar[dl]_{p}\ar[dr]^{r}\\
\Coh_{d} && \Coh_{j}\times \Coh_{d-j}.}
\end{equation*}
Here $\Coh_{j,d}$ classifies pairs $(\cQ_{j}\subset \cQ)$ of torsion sheaves of length $j$ and $d$ respectively, and the map $r$ sends $(\cQ_{j}\subset \cQ)$ to $(\cQ_{j}, \cQ/\cQ_j)$. We claim that
\begin{equation}\label{Sj ind}
\source{higher-siegel-weil-unitary-nonsingular-terms}
\Spr_{d}^{(S_{j}\times S_{d-j}, \sgn_{j}\bt1)}\cong Rp_{*}Rr^{*}(\St_{j}\bt\Qlbar).
\end{equation}
Indeed, consider the following diagram with Cartesian parallelogram
\begin{equation*}
\xymatrix{ & & \wt\Coh_{d}\ar[dl]_{\pi_{j,d}}\ar[dr]^{\wt r}\\
& \Coh_{j,d}\ar[dl]_{p}\ar[dr]^{r} & & \wt\Coh_{j}\times\wt\Coh_{d-j}\ar[dl]_{\pi_{j}\times\pi_{d-j}}\\
\Coh_{d} && \Coh_{j}\times \Coh_{d-j}
}
\end{equation*}
Here $\pi_{j}=\pi_{j}^{\Coh}$, etc. The composition $p\c \pi_{j,d}=\pi_{d}=\pi^{\Coh}_{d}$. By the proper base change theorem, we get
\begin{equation*}
\Spr_{d}=Rp_{*}R\pi_{j,d*}\Qlbar\cong Rp_{*}Rr^{*}R(\pi_{j}\times\pi_{d-j})_{*}\Qlbar=Rp_{*}Rr^{*}(\Spr_{j}\bt\Spr_{d-j}).
\end{equation*}
This isomorphism is $S_{j}\times S_{d-j}$-equivariant by checking easily over the open substack $\Coh_{d}^{\c}$. Taking $(S_{j}\times S_{d-j},\sgn_{j}\bt1)$-isotypical parts of both sides we get \eqref{Sj ind}.

By Lemma \ref{l:Spr factor} it remains to compute $P_{\cQ^{\flat}_{v}}(T)$ for each $v$. Therefore we may assume $\cQ^{\flat}=\cQ^{\flat}_{v}$.  By \eqref{Sj ind} and the Grothendieck-Lefschetz trace formula we have
\begin{eqnarray*}
P_{\cQ^{\flat}_{v}}(T)&=& \sum_{j}(-1)^{j}{\rm Tr}(\tn{Frob}, (\Spr_{d})^{(S_{j}\times S_{d-j}, \sgn_{j}\bt1)}_{\cQ^{\flat}_{v}})T^{j}\\
 &= &\sum_{j}(-1)^{j}{\rm Tr}(\tn{Frob}, Rp_{*}Rr^{*}(\St_{j}\bt\Qlbar)_{\cQ_{v}^{\flat}})T^j\\
&=& \sum_{\substack{\cR\subset \cQ^{\flat}_{v}, \\ \dim_{k_v} (\cR)=j}}(-1)^{\deg(v)j}{\rm Tr}(\tn{Frob}, (\St_{\deg(v)j})_{\cR})T^{\deg(v)j}.
\end{eqnarray*}
By Proposition \ref{p:St}, $(\St_{\deg(v)j})_{\cR}$ is zero unless $\cR\cong k_{v}^{\textnormal{op} j}$, in which case the Frobenius trace is $(-1)^{j(\deg(v)-1)}q_{v}^{j(j-1)/2}$. Let $\cQ_{v}[\varphi]$ be the kernel of the action of a uniformizer $\varphi$ at $v$. Note $V:=\cQ^{\flat}_{v}[\varphi]$ has dimension $t=t_{v}(\cQ^{\flat})$ over $k_{v}$.  Then we only need to sum over $k_{v}$-subspaces $\cR$ of $V$. The above sum becomes
\begin{equation*}
\sum_{j=0}^{t}(-1)^{j}q_{v}^{j(j-1)/2}T^{\deg(v)j}\#\Gr(j,V)(k_{v}).
\end{equation*}
Recall that the ``$q$-binomial theorem'' says that $q_v^{j(j-1)/2} \# \Gr(j, V)(k_{v})$ is the coefficient of $x^j$ in $(1+x)(1+q_vx)\ldots(1+q_v^{t-1}x)$. Making the change of variables $x=-T^{\deg(v)}$, we get
\[
\sum_{j=0}^{t}(-1)^{j}q_{v}^{j(j-1)/2}T^{\deg(v)j}\#\Gr(j,V)(k_{v}) =(1-T^{\deg(v)})(1-q_{v}T^{\deg(v)})\ldots(1-q_v^{t-1}T^{\deg(v)})
\]
as desired.

\source{higher-siegel-weil-unitary-nonsingular-terms}
\label{p:PQ trace} For $\cQ\in \Herm_{2d}(X'/X)(k)$ with support $Z$, we have
\source{higher-siegel-weil-unitary-nonsingular-terms}
\[
P_{\cQ}(T)=\prod_{v\in |X|}\mathfrak m_{v}(t'_{v}(\cQ); T^{\deg(v)}) = \prod_{v\in |Z|}\prod_{j=0}^{t'_{v}(\cQ)-1}(1-(\y(\varphi_{v})q_{v})^{j}T^{\deg(v)}).
\]

By \eqref{HSpr factor} it suffices to treat the case $\cQ$ is supported over a single place $v$. Let $\cQ^{\flat}\in \Coh_{d}(X)(k)$ be the corresponding point. If $v$ is split, we have $P_{\cQ}(T)=P_{\cQ^{\flat}}(T)$ by \eqref{PQ split}, and the formula follows from Proposition \ref{p:PQ Coh trace}. 

If $v$ is inert, let $t=t'_{v}(\cQ)=t_{v}(\cQ^{\flat})$. From the form of $P_{\cQ^{\flat}}(T)$ computed in Proposition \ref{p:PQ Coh trace}, which is valid for any extension of $k$,  the trace of the pure weight pieces of $\frP_{\cQ^{\flat}}(T)$ are separated by different powers of $q_{v}$, i.e., $q_{v}^{-i}{\rm Tr}(\tn{Frob}, \Gr^{W}_{2i\deg(v)}\frP_{\cQ^{\flat}}(T))$ is   the coefficient of $q_{v}^{i}$ in $\prod_{j=0}^{t-1}(1-q_{v}^{j}T^{\deg(v)})$.  By \eqref{PQ inert},
\begin{equation*}
P_{\cQ}(T)=\sum_{i}(-1)^{i}{\rm Tr}(\tn{Frob}, \Gr^{W}_{2i\deg(v)}\frP_{\cQ^{\flat}}(T)) =\prod_{j=0}^{t-1}(1-(-q_{v})^{j}T^{\deg(v)})
\end{equation*}
which is what we want because $\y(\varphi_{v})=-1$ in this case.

