Z \ar[r, "{(\Id, \tn{Frob})}"] & Z \times Z^{(1)}
\end{tikzcd}
\]
Then  each fiber of the composition map $V \rightarrow W\xr{h_{T}}T$ has dimension $\le d$.

 Restricting $W$ over a point $t\in T(\ov{k})$, we reduce to the case $T$ itself is the point ${\rm Spec \,}\ov{k}$. We may assume $Z={\rm Spec \,} R$ where $R=\ov k[x_{1},\ldots, x_{l}]/I$. Let $R^{(1)}=\ov k\ot_{\ov k}R\cong \ov k[\xi_{1},\ldots, \xi_{l}]/I^{(1)}$ be the base change of $R$ under $\tn{Frob}_{q}$, where $\xi_{i}=1\ot x_{i}$ . Since $h_{1}: W\to Z^{(1)}$ is smooth of relative dimension $d$,  by Zariski localizing we may assume $W=\ov k[\xi_{1},\ldots, \xi_{l}, y_{1},\ldots, y_{m+d}]/(I^{(1)}, r_{1},\ldots, r_{m})$,  with $(\pderiv{r_i}{y_j})_{j=1}^m$ having rank $m$ ($r_{i}\in \ov k[\xi_{1},\ldots, \xi_{l}, y_{1},\ldots, y_{m+d}]$). Under $h_{0}: W\to Z$, the coordinates $x_{i}$ of $Z$ pullback to functions $\ov f_{i}$ on $W$, $1\le i\le l$. We lift $f_{i}$ to polynomials $f_{i}\in \ov k[\xi_{1},\ldots, \xi_{l}, y_{1},\ldots, y_{m+d}]$. 

By definition, $V$ has the form 
\begin{eqnarray*}

V & \cong&  {\rm Spec \,}\dfrac{ \ov k[\xi_{1},\ldots, \xi_{l}, y_1, \ldots, y_m, y_{m+1} \ldots, y_{m+d}  ]}
{(I^{(1)}(\xi), g_{1},\ldots, g_{l}, r_1, \ldots, r_m)}
