Define the local version $\Sht^{r}_{\Lagr_{2d}}$ of $\Sht^{r}_{\cM_{d}}$ by the Cartesian diagram
\begin{equation}\label{Sht Lag}
\source{higher-siegel-weil-unitary-nonsingular-terms}
\xymatrix{\Sht^{r}_{\Lagr_{2d}}\ar[d] \ar[r] & \Hk^{r}_{\Lagr_{2d}}\ar[d]^{(\pr_{0},\pr_{r})}\\
\Lagr_{2d}\ar[r]^-{(\Id,\tn{Frob})} & \Lagr_{2d}\times\Lagr_{2d}}
\end{equation}
We have a decomposition into open-closed substacks
\begin{equation}
\Sht^{r}_{\Lagr_{2d}}=\coprod_{(\cQ,h)\in\Herm_{2d}(k)} \cZ^{r}_{\cQ}.

Apply Proposition \ref{p:base change} to the diagram \eqref{Sht Lagr}, the fundamental class $\z=[(\Hk^{1}_{\Lagr_{2d}})^{r} \times \Lagr_{2d}]$ and the base change map $u=g: \cA_{d}\to \Herm_{2d}$. By Proposition \ref{prop:Ad Herm smooth}, $g$ is smooth. We then have
\begin{equation}
\Phi_{\cM_{d}}^{!}g_{\Hk}^{*}[(\Hk^{1}_{\Lagr_{2d}})^{r} \times \Lagr_{2d}]=g^{*}_{\Sht}\Phi_{\Lagr_{2d}}^{!}[(\Hk^{1}_{\Lagr_{2d}})^{r} \times \Lagr_{2d}]\in \Ch_{0}(\Sht^{r}_{\cM_{d}}).
\end{equation}
Since $g_{\Hk}$ is smooth,  $g_{\Hk}^{*}[(\Hk^{1}_{\Lagr_{2d}})^{r} \times \Lagr_{2d}]=[(\Hk^{1}_{\cM_{d}})^{r} \times \Hk^{1}_{\cM_{d}}]$. The above equality then becomes \eqref{ShtM ShtLag}.

\source{higher-siegel-weil-unitary-nonsingular-terms}
\label{c:Zloc}For any $(\cE,a)\in \cA_{d}(k)$ with image $\cQ={\rm coker}\,(a)\in \Herm_{2d}(k)$, $[\cZ^{r}_{\cE}(a)]$ is the same as $[\cZ^{r}_{\cQ}]$ under the isomorphism \eqref{gSht}. In particular,
\source{higher-siegel-weil-unitary-nonsingular-terms}
\begin{equation}
\deg[\cZ^{r}_{\cE}(a)]=\deg[\cZ^{r}_{\cQ}].
\end{equation}

\source{higher-siegel-weil-unitary-nonsingular-terms}
\label{l:Lag push}
\source{higher-siegel-weil-unitary-nonsingular-terms}
The perverse sheaf $R(\upsilon_{2d})_{*}\Qlbar$ on $\Herm_{2d}$ is canonically isomorphic to $(\Spr^{\Herm}_{2d})^{S_{d}}$ (see Proposition \ref{p:SH Spr}(2)). Here the $S_{d}$-action on $\Spr^{\Herm}_{2d}$ is the restriction of the Springer $W_{d}$-action.

 We have a Cartesian diagram
\begin{equation}
\xymatrix{\wt\Herm_{2d}\ar[d]^{\l_{2d}} \ar[r]^{\wt\e_{d}} & \wt\Coh_{d}(X') \ar[d]^{\pi^{\Coh}_{X',d}} \\
\Lagr_{2d} \ar[r]^{\e'_{d}} & \Coh_{d}(X')
}
\end{equation}
where $\e'_{d}$ sends $(\cQ,h_{\cQ},\cL)$ to $\cL$ and $\wt\e_{d}$ sends $(\cQ_{1}\subset \cdots\subset\cQ_{d}\subset \cdots\subset \cQ,h)$ to $(\cQ_{1}\subset \cdots\subset\cQ_{d})$. By proper base change
\begin{equation}
R\l_{2d*}\Qlbar\cong \e'^{*}_{d}\Spr_{d, X'}.
\end{equation}
In particular, $R\l_{2d*}\Qlbar$ carries an action of $S_{d}$. Moreover, the induced $S_{d}$-action  on  $\Spr^{\Herm}_{2d}\cong R(\upsilon_{2d})_{*}R\l_{2d*}\Qlbar$ is  the restriction  of the Springer $W_{d}$-action to $S_{d}$:  this can be easily checked over $\Herm^{\c}_{2d}$, and then the statement holds over $\Herm_{2d}$ since $\Spr^{\Herm}_{2d}$ is the middle extension from its restriction to $\Herm^{\c}_{2d}$ by Proposition \ref{p:SH Spr}(2). Since  $(R\l_{2d*}\Qlbar)^{S_{d}}\cong \e'^{*}_{d}(\Spr_{d,X'})^{S_{d}}\cong \Qlbar$, we conclude that $(\Spr^{\Herm}_{2d})^{S_{d}}\cong R(\upsilon_{2d})_{*}(R\l_{2d*}\Qlbar)^{S_{d}}\cong R(\upsilon_{2d})_{*}\Qlbar$, as desired.

\source{higher-siegel-weil-unitary-nonsingular-terms}
\label{c:Lag decomp} There is a canonical decomposition 
\source{higher-siegel-weil-unitary-nonsingular-terms}
\begin{equation}\label{decomp ph}
\source{higher-siegel-weil-unitary-nonsingular-terms}
R(\upsilon_{2d})_{*}\Qlbar\cong\bigoplus_{i=0}^{d}\Spr^{\Herm}_{2d}[\r_{i}].
\end{equation}

By Lemma \ref{l:Lag push} and Frobenius reciprocity,  we have
\begin{equation}
R(\upsilon_{2d})_{*}\Qlbar\cong {\rm Hom}_{W_{d}}(\Ind_{S_{d}}^{W_{d}}\mathds{1}, \Spr^{\Herm}_{2d})=\Spr^{\Herm}_{2d}[\Ind_{S_{d}}^{W_{d}}\mathds{1}].
\end{equation}
The desired decomposition then follows from \eqref{rho i}.

\source{higher-siegel-weil-unitary-nonsingular-terms}
\label{p:action Hk1} The action of $(\upsilon_{2d})_{!}[\Hk^{1}_{\Lagr_{2d}}]$ on $R(\upsilon_{2d})_{*}\Qlbar$ preserves the decomposition \eqref{decomp ph},  and it acts on $\Spr^{\Herm}_{2d}[\r_{i}]$ by multiplication by $(d-2i)$.
\source{higher-siegel-weil-unitary-nonsingular-terms}

By Proposition \ref{p:SH Spr}(2),  $\Spr^{\Herm}_{2d}[\r_{i}]$ is the middle extension from its restriction to $\Herm^{\c}_{2d}$, it suffices to prove the same statement on $\Herm_{2d}^{\c}$. Let $I_d' \subset X_d' \times X'$ be the universal divisor $\{(D \in X_d', y \in X') \co y \in D\}$. The maps $\pr(D,y) = D$ and $q(D,y) = D-y+\sigma(y)$ define the incidence correspondence as in \cite[proof of Proposition 8.3]{YZ},
\begin{equation}\label{eq: incidence correspondence}
\source{higher-siegel-weil-unitary-nonsingular-terms}
\begin{tikzcd}
& I_d' \ar[dl, "\pr"'] \ar[dr, "q"] \\
X_d'  & & X_d' 
\end{tikzcd}
\end{equation}
Now over $\Herm_{2d}^{\c}$, the map $\Herm_{2d}^{\c}\to X^{\c}_{d}$ is smooth, and $\Hk^{1}_{\Lagr_{2d}}$ is the pullback of \eqref{eq: incidence correspondence}. We therefore reduce to checking the statement for the action of $[I'_{d}]$ on the direct image sheaf of $\nu_{d}: X'_{d}\to X_{d}$, which is done in the proof of \cite[Proposition 8.3]{YZ}.

\source{higher-siegel-weil-unitary-nonsingular-terms}
\label{p:Lef} For each $s\in S(k)$ we have
\source{higher-siegel-weil-unitary-nonsingular-terms}
\begin{equation*}
\deg((\Phi_{M}^{!}(\z_{1}\times\cdots\times\z_{r} \times [M] ))|_{\Sht_{C}|_s})={\rm Tr}(f_{!}\cla(\z_{1})\c\cdots\c f_{!}\cla(\z_{r})\c\tn{Frob}_{s}, (Rf_{!}\Qlbar)_{s}).
\end{equation*}

 We first prove the formula when $S$ is a scheme of finite type.  In this case $M,C_{i}$ are also schemes of finite type over $k$. Let $C=C_{1}\times_{M}\times\cdots\times_{M}C_{r}$ be the composition correspondence, with maps $\pr_{i}: C\to M$ for $0\le i\le r$.  Consider the diagram where all squares are Cartesian
\begin{equation}
\xymatrix{\Sht_{C}\ar[d] \ar[r] & C \ar[r]\ar[d]^{(\pr_{0},\cdots, \pr_{r}, \pr_r)} & (\prod_{i=1}^{r}C_{i} ) \times M\ar[d]^{\prod (\pr^{i}_{0}, \pr^{i}_{1}) \times \Delta}\\
M^{r+1} \ar[d]_{\pr_{0}} \ar[r]^{\Phi_{1}} & M^{r+2}\ar[d]^{(\pr_{0}, \pr_{r+1})} \ar[r]^{\Phi_{2}} & M^{2r+2}\\
M\ar[r]_-{(\Id,\tn{Frob}_{M})} & M\times M}
\end{equation}
Here
\begin{align*}
\Phi_{1}(\xi_{0},\cdots,  \xi_{r-1}, \xi_r) & =(\xi_{0},\cdots, \xi_r, \tn{Frob}_{M}(\xi_{0})),\\
\Phi_{2}(\xi_{0},\cdots, \xi_r,\xi_{r+1}) & =(\xi_{0},\xi_{1},\xi_{1},\cdots,\xi_{r},\xi_{r}, \xi_{r+1}).
\end{align*}
We have $\Phi_{M}=\Phi_{2}\c\Phi_{1}$. Let $\z=\Phi_{2}^{!}(\z_{1}\times\z_{2}\times\cdots\times\z_{r} \times [M])\in \Ch_{N}(C)$. 

On the one hand, by the transitivity of the Gysin maps, 
\begin{equation}\label{Phizz}
\source{higher-siegel-weil-unitary-nonsingular-terms}
\Phi^{!}_{M}(\z_{1}\times\cdots\times\z_{r} \times [M] )=\Phi_{1}^{!}(\z)=(\Id,\tn{Frob}_{M})^{!}(\z).
\end{equation}
Applying the Lefschetz trace formula \cite[Proposition  A.12]{YZ}, we get
\begin{equation}\label{deg tr z}
\source{higher-siegel-weil-unitary-nonsingular-terms}
\deg((\Id,\tn{Frob}_{M})^{!}(\z)|_{\Sht_{C}|_s})={\rm Tr}(f_{!}\cla(\z)\c \tn{Frob}, (Rf_{!}\Qlbar)_{s}).
\end{equation}
One the other hand, by a diagram chase, we see that $\cla(\z)$ is the composition of the cohomological correspondences $\cla(\z_{i})$ ($1\le i\le r$), hence $f_{!}\cla(\z)\in {\rm End}(Rf_{!}\Qlbar)$ is the composition of $f_{!}\cla(\z_{1})\c f_{!}\cla(\z_{2})\c\cdots\c f_{!}\cla(\z_{r})$. Combining this fact with \eqref{Phizz} and \eqref{deg tr z} we get the desired formula.

Now consider the general case where $S$ is a stack locally of finite type over $k$ and we aim to prove the formula for $s\in S(k)$. We claim that there exists a scheme $S'$ of finite type over $k$ and a smooth map $u: S'\to S$ such that $u(S'(k))$ contains $s$.  Indeed, pick any smooth map $u_{1}: S_{1}\to S$ with $S_{1}$ a scheme of finite type over $k$, such that  $s$ is contained in the image of $u$. Let $s_{1}\in S_{1}({\mathbb F}_{q^{m}})$ be a point that maps to $s$. Let $(S_{1}/S)^{m}$ be the $m$-fold fibered product of $S_1$ over $S$, based changed to $\ol{k}$. We equip  $(S_{1}/S)^{m}$ with the $\tn{Frob}$-descent datum given by $(x_{1},\cdots, x_{m})\mapsto (\tn{Frob}(x_{m}), \tn{Frob}(x_{1}),\cdots, \tn{Frob}(x_{m-1}))$. This gives a descent of $(S_{1}/S)^{m}$ to a scheme $S'$ over $k$ equipped with a map $u:S'\to S$ which is still smooth since $u_{1}$ is. Now $s_{1}$ gives rise to a $k$-point $s'=(s_{1},\tn{Frob}(s_{1}),\cdots, \tn{Frob}^{m-1}(s_{1}))\in S'(k)$ such that $u(s')=s$. 

