\source{squarefree-values-polynomial-discriminants}
\label{thmaingencong}
\source{squarefree-values-polynomial-discriminants}
Let $\kappa$ be a positive integer and let $\Sigma$ be a $\kappa$-acceptable collection of local specifications. Then
\begin{equation*}
\#{\mathbb V}(\Sigma)_X=\Vol(\Sigma_{\infty,H<1})\prod_p\Vol(\Sigma_p)\cdot
X^{n(n+1)/2}+O_\epsilon(X^{n(n+1)/2-\min\{1/5,1/(2\kappa)\}+\epsilon}),
\end{equation*}
where $\Sigma_{\infty,H<1}$ is the set of elements in $\Sigma_\infty$
having height less than $1$, the volumes of sets in $\Vmn({\mathbb Z}_p)$
$($resp.\ $\Vmn(R))$ are computed with respect to the Haar-measures
normalized so that $\Vmn({\mathbb Z}_p)$ has volume~$1$ $($resp.\ $\Vmn({\mathbb Z})$ has
covolume~1$)$, and where the implied constant depends only on $n$ and $\Sigma$.

\source{squarefree-values-polynomial-discriminants}
\label{lemlin}
\source{squarefree-values-polynomial-discriminants}
The number of elements in $\Vmn({\mathbb Z})_X$ that have a rational linear factor
is bounded by $O(X^{n(n+1)/2-n+1}\log X)$.

\source{squarefree-values-polynomial-discriminants}
\label{unif}
\source{squarefree-values-polynomial-discriminants}
Let ${\mathbb U}_{m,X}$ denote the set of elements in ${\mathbb U}_m$ having height
bounded by $X$. For any positive real number $M$, we have
\begin{equation}\label{equ2}
\source{squarefree-values-polynomial-discriminants}
\sum_{\substack{m>M\\ m\;\mathrm{ squarefree}}}
\#{\mathbb U}_{m,X}=O_\epsilon(X^{n(n+1)/2+\epsilon}/\sqrt{M})+O_\epsilon(X^{n(n+1)/2-1/5+\epsilon}).
\end{equation}

\begin{equation}\label{eq:haha}
\source{squarefree-values-polynomial-discriminants}
\sum_{\substack{m>X^{1/\kappa}\\ m\;\mathrm{ squarefree}}}\#{\mathbb W}_{m}(\Sigma)_X \leq \sum_{\substack{m'>X^{1/\kappa-\epsilon}\\ m'\;\mathrm{ squarefree}}}\#{\mathbb W}_{m',X}.
\end{equation}

