Let $\hat{\omega}^{\mathrm{univ}}$ be as in
Lemma~\ref{LemmaBettiOnUniversalCovering}. Then under the change of
coordinates \eqref{EqChangeOfCoor}, we have 
$\hat{\omega}^{\mathrm{univ}}=2\tran{(\mathrm{d}a)} \wedge \mathrm{d}
b$.

 For the moment we write $Z = X + \sqrt{-1}Y$ with $X$ and $Y$ the real and
imaginary part of $Z\in\mathfrak{H}_g$, respectively. 
Note that $w = a + Zb = (a + X b) + \sqrt{-1}Y b$. Hence
$Y^{-1}(\mathrm{Im}w) = b$ and $\mathrm{d}w = \mathrm{d}a +
Z\mathrm{d}b + \mathrm{d}Z  b$. Using this and noting that $Z$
is symmetric, we have that \eqref{eq:bettiformaltformula} becomes
\begin{equation*}

\begin{aligned}
    \hat \omega^{\mathrm{univ}} &=\sqrt{-1}\left( \sqrt{-1}\tran{(\mathrm{d}
        b)} Y + \tran{(\mathrm{d} b)} X + \tran{(\mathrm{d} a)}\right) \wedge Y^{-1}
    \left(\mathrm{d} a + X \mathrm{d} b - \sqrt{-1} Y \mathrm{d} b\right) \\
    &=\sqrt{-1}\bigl(\sqrt{-1} \tran{(\mathrm{d} b)}\wedge\mathrm{d} a + \tran{(\mathrm{d} b)}\wedge
    Y \mathrm{d} b + \tran{(\mathrm{d} b)} X \wedge Y^{-1} \mathrm{d} a+ \tran{(\mathrm{d}
      b)}X\wedge 
    Y^{-1}X \mathrm{d} b + \\ 
    &\phantom{=\sqrt{-1}\bigl(}\tran{(\mathrm{d} a)} \wedge Y^{-1} \mathrm{d} a 
    + \tran{(\mathrm{d} a)}\wedge Y^{-1}X\mathrm{d} b -
    \sqrt{-1} \tran{(\mathrm{d} a)}\wedge \mathrm{d} b\bigr).
\end{aligned}
\end{equation*}

 Many terms will vanish. Indeed, if $M$ is a
matrix, then $\tran{(\mathrm{d} b)} \wedge M \mathrm{d} a = - \tran{(\mathrm{d}
a)}\wedge \tran{M} \mathrm{d} b $. As $\tran{(XY^{-1})} = Y^{-1}X$ and as
$\tran{(\mathrm{d} b)} X \wedge Y^{-1} \mathrm{d} a=\tran{(\mathrm{d}
b)} \wedge XY^{-1} \mathrm{d} a$ we find
$\tran{(\mathrm{d} b)}X \wedge Y^{-1} \mathrm{d} a + \tran{(\mathrm{d} a)}\wedge
 Y^{-1}X \mathrm{d} b=0$. Observe that $Y$ is symmetric, and so $\tran{(\mathrm{d}
b)}\wedge Y \mathrm{d} b = -\tran{(\mathrm{d} b)}\wedge Y\mathrm{d} b$ vanishes. Arguing
along the same line and using that
$Y^{-1}$ and $XY^{-1}X$ are  symmetric we find $\tran{(\mathrm{d}
a)}\wedge Y^{-1} \mathrm{d} a = 0$ and $\tran{(\mathrm{d} b)}X\wedge Y^{-1}X=\tran{(\mathrm{d} b)}\wedge XY^{-1}X \mathrm{d}
b=0$. We are left with
$    \hat \omega^{\mathrm{univ}} = 2\tran{(\mathrm{d} a)} \wedge \mathrm{d} b$.

\begin{equation*}

